/* Additional original course units; teach every source before using it in a check. */
(()=>{
'use strict';
const base=window.WordamiSkillsContent;if(!base)return;
const lt=LANG.code==='lt',pick=p=>p[lt?0:1];
const rows=[
{id:'A1-shopping',band:'A1',theme:'Buy everyday things',focus:'Understand an item, quantity and price, and make a short purchase request.',
 phrases:[['parduotuvė','tienda','shop'],['obuoliai','manzanas','apples'],['du obuoliai','dos manzanas','two apples'],['trys eurai','treinta pesos','three euros / thirty pesos'],['Norėčiau duonos.','Quisiera pan.','I would like bread.'],['Kiek kainuoja?','¿Cuánto cuesta?','How much does it cost?'],['Mokėsiu kortele.','Voy a pagar con tarjeta.','I will pay by card.'],['Ačiū, viso gero!','Gracias, ¡hasta luego!','Thank you, goodbye!']],
 lesson:['Say the item and quantity clearly. A price and an item count answer different questions.',lt?'Compare the Lithuanian forms: du obuoliai names the items; perku du obuolius uses the object form, and norėčiau trijų obuolių expresses the requested amount. Learn each complete pattern.':'Use quisiera for a polite request. Keep the noun plural after dos or tres: dos manzanas, tres manzanas.','The Lithuanian case uses euros; the Mexican Spanish case uses pesos. Keep each source’s amount separate.'],
 reading:['Parduotuvėje perku du obuolius ir duonos. Obuoliai kainuoja tris eurus. Mokėsiu kortele. Ačiū, viso gero!','En la tienda compro dos manzanas y pan. Las manzanas cuestan treinta pesos. Voy a pagar con tarjeta. Gracias, ¡hasta luego!','At the shop I buy two apples and bread. The apples cost three euros / thirty pesos. I will pay by card. Thank you, goodbye!'],
 listen:['Laba diena! Norėčiau trijų obuolių. Kiek kainuoja? Keturi eurai? Gerai. Mokėsiu grynaisiais. Ačiū!','¡Buenos días! Quisiera tres manzanas. ¿Cuánto cuestan? ¿Cuarenta pesos? Está bien. Voy a pagar en efectivo. ¡Gracias!','The customer asks for three apples, confirms a price of four euros / forty pesos, and pays in cash.'],
 readQ:[['How many apples are bought?',['Two','Three','Four'],0],['How will the customer pay?',['In cash','By card','With a voucher'],1],['What other item is bought?',['Milk','Tea','Bread'],2]],
 hearQ:[['How many apples are requested?',['Two','Three','Four'],1],['How will this customer pay?',['In cash','By card','The friend will pay'],0],['Which amount is confirmed?',lt?['Three euros','Ten euros','Four euros']:['Thirty pesos','Ten pesos','Forty pesos'],2]],
 turns:[['Laba diena! Ko norėtumėte?','¡Buenos días! ¿Qué desea?','Hello! What would you like?','Request an item and give a quantity.'],['Ar norėtumėte dar ko nors?','¿Desea algo más?','Would you like anything else?','Add one item or politely say that is all.'],['Mokėsite kortele ar grynaisiais?','¿Va a pagar con tarjeta o en efectivo?','Will you pay by card or in cash?','State your payment method and close politely.']],
 production:['Describe a small shopping trip, including the items, one quantity and your payment method.',['Name the items.','Keep quantities and prices distinct.','Make the payment method clear.']],
 mediation:'Tell a friend the difference between the two customers’ purchases and payment methods.',
 project:{title:'A shopping message',audience:'A friend buying things for you',brief:'Write a short message asking your friend to buy everyday items. Use real or invented details.',goals:['Name two items.','Give at least one quantity.','Add a polite closing.'],range:[25,60]}},
{id:'A1-home',band:'A1',theme:'Welcome someone to your home',focus:'Understand simple room descriptions and give a visitor useful information.',
 phrases:[['Mano namai maži.','Mi casa es pequeña.','My home is small.'],['Čia yra virtuvė.','Aquí está la cocina.','Here is the kitchen.'],['Kambarys šviesus.','El cuarto es luminoso.','The room is bright.'],['Vonios kambarys yra čia.','El baño está aquí.','The bathroom is here.'],['Prašau užeiti.','Pasa, por favor.','Please come in.'],['Atsisėsk čia.','Siéntate aquí.','Sit here.'],['Ar nori arbatos?','¿Quieres un té?','Would you like tea?'],['Raktas yra ant stalo.','La llave está sobre la mesa.','The key is on the table.']],
 lesson:['Use a short sentence to locate each room or object.',lt?'Compare agreement: kambarys šviesus is singular; namai šviesūs is plural. The location pattern šalia virtuvės means beside the kitchen.':'Use es for a quality and está for a location: mi casa es pequeña, el baño está aquí. Adjectives agree with the noun.','For a visitor, useful information is more important than listing every object in the home.'],
 reading:['Labas! Prašau užeiti. Mano namai maži, bet šviesūs. Čia yra virtuvė. Vonios kambarys yra šalia virtuvės. Raktas yra ant stalo. Ar nori arbatos?','¡Hola! Pasa, por favor. Mi casa es pequeña, pero luminosa. Aquí está la cocina. El baño está junto a la cocina. La llave está sobre la mesa. ¿Quieres un té?','The host welcomes a visitor to a small, bright home. The bathroom is beside the kitchen. The key is on the table, and the host offers tea.'],
 listen:['Labas! Mano butas yra antrame aukšte. Užeik. Šis kambarys didelis, o virtuvė maža. Tavo raktas yra ant kėdės. Gal nori vandens?','¡Hola! Mi departamento está en el segundo piso. Pasa. Este cuarto es grande y la cocina es pequeña. Tu llave está sobre la silla. ¿Quieres agua?','The flat is on the second floor. The room is large and the kitchen small. The visitor’s key is on the chair, and the host offers water.'],
 readQ:[['Where is the bathroom?',['Beside the kitchen','Outside the building','Beside the bedroom'],0],['Where is the key?',['On the chair','On the table','In a bag'],1],['What drink is offered?',['Coffee','Water','Tea'],2]],
 hearQ:[['Which floor is mentioned?',['The first','The second','The third'],1],['Where is this key?',['On the chair','On the table','By the door'],0],['How is the kitchen described?',['Large','Dark','Small'],2]],
 turns:[['Kur yra virtuvė?','¿Dónde está la cocina?','Where is the kitchen?','Tell your visitor where the kitchen is.'],['Kur galiu padėti savo krepšį?','¿Dónde puedo dejar mi bolsa?','Where can I put my bag?','Suggest a simple place for the bag.'],['Ar galiu gauti vandens?','¿Me puedes dar agua?','Could I have water?','Respond politely to the visitor’s request.']],
 production:['Welcome a visitor and describe a real or invented home.',['Describe one room.','Locate a useful object.','Make a simple offer to the visitor.']],
 mediation:'Leave a voice note telling the visitor where to find the key in each of the two homes. Do not mix up the table and chair.',
 project:{title:'A note for a visitor',audience:'A friend arriving at your home',brief:'Write a useful arrival note for a real or invented home.',goals:['Welcome the visitor.','Describe where to find a room or object.','Give one useful instruction or offer.'],range:[30,70]}},
{id:'A2-services',band:'A2',theme:'Arrange and change an appointment',focus:'Follow opening times, explain a booking problem and agree a replacement.',
 phrases:[['Norėčiau užsiregistruoti.','Quisiera hacer una cita.','I would like to make an appointment.'],['Ar turite laisvą laiką antradienį?','¿Tiene algún horario disponible el martes?','Do you have an available time on Tuesday?'],['Galiu ateiti po pietų.','Puedo ir por la tarde.','I can come in the afternoon.'],['Deja, tas laikas netinka.','Lo siento, ese horario no me viene bien.','Unfortunately, that time does not work for me.'],['Norėčiau pakeisti susitikimo laiką.','Quisiera cambiar la hora de la cita.','I would like to change the appointment time.'],['Ar galima penktadienį?','¿Se puede el viernes?','Is Friday possible?'],['Prašau patvirtinti laiką.','Por favor, confirme el horario.','Please confirm the time.'],['Atsinešiu dokumentus.','Voy a llevar los documentos.','I will bring the documents.']],
 lesson:['A booking exchange needs the day, time and any required action.','Use a reason when declining a time, then offer a possible alternative.','Keep the old booking separate from the new one. “Change” does not mean “cancel without replacing”.'],
 reading:['Laba diena. Jūsų susitikimas dėl dokumentų yra antradienį dešimtą valandą. Prašome atvykti dešimt minučių anksčiau ir atsinešti dokumentus. Jei šis laikas netinka, parašykite mums. Penktadienį turime laisvą laiką trečią valandą po pietų. Naują laiką reikia patvirtinti iki ketvirtadienio.','Buenos días. Su cita para revisar los documentos es el martes a las diez. Por favor, llegue diez minutos antes y traiga los documentos. Si ese horario no le viene bien, escríbanos. El viernes tenemos un espacio a las tres de la tarde. Debe confirmar el nuevo horario antes del jueves.','The document appointment is Tuesday at ten. Arrive ten minutes early and bring documents. Friday at three in the afternoon is available as a replacement, which must be confirmed before Thursday.'],
 listen:['Laba diena, skambinu dėl savo susitikimo. Antradienį ryte turiu dirbti, todėl negaliu atvykti. Norėčiau užsiregistruoti penktadienį trečią valandą. Atsinešiu dokumentus ir atvyksiu truputį anksčiau. Prašau patvirtinti naują laiką žinute. Ačiū už pagalbą.','Buenos días, llamo por mi cita. El martes por la mañana tengo que trabajar y no puedo ir. Quisiera cambiarla al viernes a las tres. Voy a llevar los documentos y llegar un poco antes. Por favor, confirmen el nuevo horario por mensaje. Gracias por su ayuda.','The caller cannot attend Tuesday morning because of work. They ask for Friday at three, will bring documents and arrive early, and request confirmation by message.'],
 readQ:[['What is the original appointment?',['Tuesday at ten','Friday at ten','Thursday at three'],0],['What should the visitor bring?',['A ticket','Documents','Food'],1],['When must a replacement be confirmed?',['After Friday','On Saturday','Before Thursday'],2]],
 hearQ:[['Why does the caller change the booking?',['They are travelling','They have to work','They lost the address'],1],['Which time do they request?',['Friday at three','Tuesday at three','Friday at ten'],0],['How do they request confirmation?',['By letter','Only in person','By message'],2]],
 turns:[['Kokiai dienai norėtumėte užsiregistruoti?','¿Para qué día quisiera la cita?','Which day would you like an appointment?','Request a day and a time of day.'],['Tą rytą laisvo laiko nėra. Ar tiktų popietė?','Esa mañana no hay lugar. ¿Le sirve por la tarde?','That morning is full. Would the afternoon work?','Accept the afternoon or propose another day with a reason.'],['Kaip norėtumėte gauti patvirtinimą?','¿Cómo desea recibir la confirmación?','How would you like confirmation?','Request confirmation and mention what you will bring.']],
 production:['Explain an appointment change and propose a replacement.',['State the original appointment.','Explain why it needs to change.','Give a replacement and request confirmation.']],
 mediation:'Explain the office’s instructions and the caller’s requested change to someone helping organise the visit.',
 project:{title:'Change a booking',audience:'A service office',brief:'Write a polite message changing an invented appointment.',goals:['Identify the original booking.','Explain the problem and propose an alternative.','Request confirmation and acknowledge any required documents.'],range:[65,110]}},
{id:'A2-work',band:'A2',theme:'Plan a working day',focus:'Compare routines, understand a changed schedule and explain practical responsibilities.',
 phrases:[['Darbą pradedu devintą.','Empiezo a trabajar a las nueve.','I start work at nine.'],['Pirmiausia patikrinu žinutes.','Primero reviso los mensajes.','First I check messages.'],['Po susitikimo paskambinsiu klientui.','Después de la reunión voy a llamar al cliente.','After the meeting I will call the client.'],['Pietauju pusę pirmos.','Como a las doce y media.','I have lunch at half past twelve.'],['Šiandien dirbu iš namų.','Hoy trabajo desde casa.','Today I work from home.'],['Rytoj būsiu biure.','Mañana voy a estar en la oficina.','Tomorrow I will be at the office.'],['Man reikia pagalbos.','Necesito ayuda.','I need help.'],['Galime pasidalyti užduotis.','Podemos repartir las tareas.','We can divide the tasks.']],
 lesson:['Time expressions and sequence words show how a routine is organised.','A temporary change today does not replace every part of someone’s normal routine.','When sharing work, say who will do what and when it is needed.'],
 reading:['Paprastai darbą pradedu devintą valandą biure. Pirmiausia patikrinu žinutes, o dešimtą susitinku su komanda. Po susitikimo paskambinu klientams. Pietauju pusę pirmos. Šiandien dirbu iš namų, nes laukiu meistro. Į komandos susitikimą prisijungsiu internetu. Klientams paskambinsiu po pietų.','Normalmente empiezo a trabajar a las nueve en la oficina. Primero reviso los mensajes y a las diez me reúno con el equipo. Después llamo a los clientes. Como a las doce y media. Hoy trabajo desde casa porque espero a un técnico. Voy a conectarme a la reunión por internet y llamar a los clientes por la tarde.','Normally the writer starts at nine in the office, checks messages, meets the team at ten and then calls clients. Lunch is at twelve thirty. Today they work at home waiting for a technician, attend online and move client calls to the afternoon.'],
 listen:['Labas, rytoj mūsų susitikimas bus vienuoliktą, o ne dešimtą. Ryte prašau paruošti klientų sąrašą. Aš patikrinsiu dokumentus. Po pietų kartu paskambinsime naujam klientui. Jei nespėsi paruošti sąrašo, pranešk iki vienuoliktos. Galėsime pasidalyti darbą.','Hola, mañana nuestra reunión va a ser a las once, no a las diez. Por la mañana prepara la lista de clientes, por favor. Yo voy a revisar los documentos. Por la tarde llamamos juntos a un cliente nuevo. Si no terminas la lista, avísame antes de las once. Podemos repartir el trabajo.','Tomorrow’s meeting moves from ten to eleven. The listener should prepare a client list; the speaker will check documents. They will call a new client together in the afternoon. If the list will not be ready, the listener should say so before eleven.'],
 readQ:[['Why is the writer at home today?',['Waiting for a technician','The office has closed permanently','They are on holiday'],0],['What stays in the morning?',['The client calls','The team meeting','Lunch'],1],['When is the normal lunch break?',['At eleven','At one thirty','At twelve thirty'],2]],
 hearQ:[['What is the new meeting time?',['Ten','Eleven','Twelve'],1],['Who checks the documents?',['The speaker','The new client','The listener alone'],0],['What should happen if the list is not ready?',['Cancel every call','Say nothing until afternoon','Notify the speaker before eleven'],2]],
 turns:[['Kaip paprastai atrodo jūsų darbo rytas?','¿Cómo es normalmente su mañana de trabajo?','What is your normal working morning like?','Describe two activities in order.'],['Rytoj susitikimas prasidės valanda vėliau. Ar jums tinka?','Mañana la reunión empieza una hora más tarde. ¿Le viene bien?','Tomorrow the meeting starts an hour later. Does that work?','Respond and explain any practical effect on your day.'],['Kaip galėtume pasidalyti užduotis?','¿Cómo podemos repartir las tareas?','How can we divide the tasks?','Offer to do one task and ask the partner to do another.']],
 production:['Describe a routine and explain how a change affects it.',['Give a clear normal sequence.','Distinguish the temporary change.','Explain who will do the necessary tasks.']],
 mediation:'Brief a colleague on which timetable details concern today’s home-working arrangement and which concern tomorrow’s changed meeting.',
 project:{title:'A useful team update',audience:'Your team',brief:'Write an update explaining a temporary schedule change and how work will be shared.',goals:['State the change and a reason.','Give clear times or sequence.','Assign responsibilities and say when help is needed.'],range:[70,120]}}
,{id:'B1-appointments',band:'B1',theme:'Solve an access problem',focus:'Explain a practical service problem, follow instructions and check what remains unresolved.',
 phrases:[['Norėčiau paaiškinti, kas atsitiko.','Quisiera explicar lo que pasó.','I would like to explain what happened.'],['Užsiregistravau praėjusią savaitę.','Hice la cita la semana pasada.','I made the appointment last week.'],['Patvirtinimo negavau.','No recibí la confirmación.','I did not receive confirmation.'],['Gal įvyko klaida?','¿Habrá algún error?','Could there have been a mistake?'],['Turiu žinutės kopiją.','Tengo una copia del mensaje.','I have a copy of the message.'],['Ką turėčiau daryti toliau?','¿Qué debería hacer ahora?','What should I do next?'],['Ar teisingai supratau?','¿Entendí bien?','Have I understood correctly?'],['Prašau atsiųsti informaciją raštu.','Por favor, envíeme la información por escrito.','Please send the information in writing.']],
 lesson:['A useful explanation separates what you did, what response you expected and what actually happened.','Distinguish evidence of a request from evidence that a booking was confirmed.','Repeat the practical next step in your own words to check understanding.'],
 reading:['Praėjusią savaitę internetu užpildžiau registracijos formą, tačiau patvirtinimo negavau. Maniau, kad susitikimas jau paskirtas, todėl pirmadienį atvykau į klientų aptarnavimo centrą. Darbuotoja mano pavardės sąraše nerado. Parodžiau išsaugotą žinutę. Paaiškėjo, kad tai buvo tik pranešimas apie gautą prašymą, o ne susitikimo patvirtinimas. Darbuotoja pasiūlė laisvą laiką trečiadienį ir pažadėjo atsiųsti patvirtinimą. Šį kartą paprašiau raštu nurodyti ne tik laiką, bet ir adresą bei reikalingus dokumentus.','La semana pasada llené un formulario de registro por internet, pero no recibí la confirmación. Pensé que la cita ya estaba hecha y el lunes fui al centro de atención. La empleada no encontró mi nombre en la lista. Le mostré el mensaje que había guardado. Resultó que solo era un aviso de que habían recibido la solicitud, no una confirmación de la cita. Me ofreció un espacio el miércoles y prometió enviar la confirmación. Esta vez pedí que el mensaje incluyera la hora, la dirección y los documentos necesarios.','The writer submitted an online request and mistook its receipt for an appointment confirmation. At the centre on Monday, their name was absent. The saved message established only receipt. An employee offered Wednesday. The writer requested written confirmation with time, address and required documents.'],
 listen:['Patikrinome jūsų prašymą. Jis buvo gautas penktadienį, bet trūko telefono numerio, todėl negalėjome susisiekti. Prašome šiandien atsiųsti numerį elektroniniu paštu. Galime pasiūlyti susitikimą ketvirtadienį antrą valandą. Kol negausite atskiro patvirtinimo, šis laikas dar nėra galutinai paskirtas. Jei ketvirtadienis netinka, parašykite, kuriomis dienomis galite atvykti. Prašymo iš naujo pildyti nereikia.','Revisamos su solicitud. La recibimos el viernes, pero faltaba el teléfono y no pudimos comunicarnos. Envíenos hoy su número por correo electrónico, por favor. Podemos ofrecerle una cita el jueves a las dos. Ese horario todavía no es definitivo: tiene que recibir una confirmación aparte. Si no puede venir el jueves, indique qué días tiene disponibles. No necesita llenar otra vez la solicitud.','The request arrived Friday but lacked a phone number. The listener should email it today. Thursday at two is offered provisionally and needs separate confirmation. If unavailable, state alternative days. There is no need to submit the entire request again.'],
 readQ:[['What did the saved message establish?',['Receipt of a request','A guaranteed appointment','A completed service'],0],['What new day was offered?',['Monday','Wednesday','Friday'],1],['Why request further details in writing?',['To cancel the request','To avoid speaking to staff','To clarify the practical arrangements'],2]],
 hearQ:[['What prevented contact?',['An incorrect address','A missing phone number','A closed office'],1],['What is the status of Thursday at two?',['A provisional offer awaiting confirmation','A cancelled appointment','A completed visit'],0],['What is unnecessary?',['Sending a phone number','Suggesting available days','Submitting the whole request again'],2]],
 turns:[['Kokią žinutę gavote pateikę prašymą?','¿Qué mensaje recibió al enviar la solicitud?','What message did you receive after submitting the request?','Explain what you received without assuming it confirmed a booking.'],['Ar galėtumėte patikslinti savo duomenis?','¿Podría confirmar sus datos?','Could you clarify your details?','Supply invented contact details or explain what needs correcting.'],['Ką darysite, jei patvirtinimas neateis?','¿Qué hará si no llega la confirmación?','What will you do if confirmation does not arrive?','State a reasonable follow-up and check the next step.']],
 production:['Explain a fictional booking problem and the steps needed to resolve it.',['Distinguish the request from its confirmation.','Support the explanation with a relevant detail.','Check what still needs to happen.']],
 mediation:'Explain to a family member why neither an acknowledgement nor a provisional time should be treated as a final booking.',
 project:{title:'Clarify an unresolved request',audience:'A service centre',brief:'Write a clear follow-up about an invented booking problem.',goals:['Describe what you submitted and received.','Identify the unresolved point without accusing anyone.','Request a specific written next step.'],range:[120,190]}},
{id:'B1-community',band:'B1',theme:'Organise a community event',focus:'Follow proposals and constraints, explain a choice and coordinate practical action.',
 phrases:[['Siūlau surengti bendruomenės susitikimą.','Propongo organizar una reunión comunitaria.','I suggest organising a community meeting.'],['Renginys vyktų šeštadienį.','El evento sería el sábado.','The event would be on Saturday.'],['Turime atsižvelgti į orą.','Tenemos que tomar en cuenta el tiempo.','We must consider the weather.'],['Salė talpina trisdešimt žmonių.','En el salón caben treinta personas.','The room holds thirty people.'],['Lauke būtų daugiau vietos.','Afuera habría más espacio.','There would be more space outside.'],['Galėtume paprašyti savanorių pagalbos.','Podríamos pedir ayuda a voluntarios.','We could ask volunteers for help.'],['Kas galėtų pasirūpinti kėdėmis?','¿Quién podría encargarse de las sillas?','Who could take care of the chairs?'],['Galutinį planą paskelbsime penktadienį.','Publicaremos el plan final el viernes.','We will publish the final plan on Friday.']],
 lesson:['A proposal is not a confirmed arrangement: notice conditional language and confirmation dates.','Explain why a constraint changes a recommendation, rather than merely listing options.','A useful plan assigns responsibilities and states how people will hear about changes.'],
 reading:['Mūsų bendruomenė planuoja šeštadienio popietę surengti knygų mainus. Pirmasis pasiūlymas buvo susitikti parke, nes ten būtų daugiau vietos šeimoms. Tačiau keli kaimynai priminė, kad gali lyti. Bibliotekos salė apsaugotų nuo lietaus, bet joje telpa tik trisdešimt žmonių. Siūlome registruotis iš anksto. Jei užsiregistruos daugiau žmonių, renginį padalysime į dvi dalis. Du savanoriai jau pažadėjo atnešti kėdes. Dar ieškome žmogaus, kuris pasirūpintų skelbimu. Galutinį planą paskelbsime penktadienį.','Nuestra comunidad planea organizar un intercambio de libros el sábado por la tarde. La primera propuesta fue reunirnos en el parque porque habría más espacio para las familias. Sin embargo, algunos vecinos recordaron que podría llover. El salón de la biblioteca nos protegería de la lluvia, pero solo caben treinta personas. Proponemos que la gente se registre antes. Si se inscriben más personas, dividiremos el evento en dos sesiones. Dos voluntarios ya ofrecieron llevar sillas. Todavía buscamos a alguien que prepare el anuncio. Publicaremos el plan final el viernes.','A Saturday afternoon book exchange was first proposed for the park. Rain risk favours the library room, limited to thirty people. Advance registration will show whether two sessions are needed. Chairs have volunteers, but the announcement still needs someone. The final plan will be published Friday.'],
 listen:['Labas, turiu naujienų dėl knygų mainų. Užsiregistravo keturiasdešimt žmonių, todėl salėje rengsime dvi grupes. Pirmoji pradės antrą, antroji ketvirtą valandą. Į parką neisime, net jeigu oras pagerės: dalyviams jau išsiuntėme bibliotekos adresą. Prašau šiandien paruošti aiškų skelbimą su abiem laikais. Kėdėmis pasirūpins savanoriai, o aš pasitiksiu pirmą grupę.','Hola, tengo noticias del intercambio de libros. Se registraron cuarenta personas, así que vamos a organizar dos grupos en el salón. El primero empieza a las dos y el segundo a las cuatro. No iremos al parque aunque mejore el tiempo, porque ya enviamos la dirección de la biblioteca. Prepara hoy un anuncio claro con los dos horarios, por favor. Los voluntarios se encargan de las sillas y yo recibo al primer grupo.','Forty people registered, so there will be two indoor groups at two and four. The location will remain the library even if weather improves because the address has already been sent. The listener should prepare an announcement today. Volunteers handle chairs; the speaker welcomes group one.'],
 readQ:[['Why was the park attractive?',['More space for families','It had a roof','It was already booked'],0],['Which task remains unassigned?',['Bringing chairs','Preparing an announcement','Finding books for everyone'],1],['What determines whether two sessions are needed?',['The price of chairs','The library’s opening year','The number registering'],2]],
 hearQ:[['What change is now confirmed?',['A move to the park','Two indoor groups','Cancellation of the event'],1],['Why keep the library even in good weather?',['The address has already been sent','The park no longer exists','Volunteers refuse outdoor work'],0],['What should the listener do today?',['Buy forty chairs','Welcome both groups','Prepare an announcement with both times'],2]],
 turns:[['Kuri vieta renginiui būtų tinkamiausia?','¿Qué lugar sería más adecuado para el evento?','Which location would be most suitable?','Recommend a location and explain a practical reason.'],['O ką darysime, jei dalyvių bus per daug?','¿Y qué haremos si hay demasiados participantes?','What will we do if too many people attend?','Propose a workable capacity plan.'],['Kokią užduotį galėtumėte atlikti?','¿De qué tarea podría encargarse?','Which task could you take responsibility for?','Offer a specific contribution and a deadline.']],
 production:['Explain an event plan and how you will handle a practical constraint.',['Describe the event’s purpose.','Justify one planning choice.','Assign a task and explain how changes will be communicated.']],
 mediation:'Brief a volunteer on the difference between the initial proposal and the confirmed two-session plan.',
 project:{title:'An event announcement',audience:'Community participants',brief:'Write a practical announcement using the updated plan or your own consistent invented plan.',goals:['Give the place and relevant times.','Explain registration or group arrangements.','Make any required action clear.'],range:[120,190]}}
,{id:'B2-workplace',band:'B2',theme:'Negotiate a working arrangement',focus:'Evaluate competing needs, negotiate conditions and make a qualified recommendation.',
 phrases:[['Siūlomas modelis turėtų būti lankstus.','El modelo propuesto debería ser flexible.','The proposed model should be flexible.'],['Svarbu sutarti dėl aiškių kriterijų.','Es importante acordar criterios claros.','It is important to agree clear criteria.'],['Produktyvumo negalima vertinti vien pagal buvimą biure.','La productividad no se puede medir solo por la presencia en la oficina.','Productivity cannot be judged only by office attendance.'],['Vis dėlto bendradarbiavimui reikia laiko kartu.','Aun así, colaborar requiere tiempo compartido.','Nevertheless, collaboration requires shared time.'],['Galėtume išbandyti šį variantą.','Podríamos poner a prueba esta opción.','We could trial this option.'],['Ši išimtis turėtų būti pagrįsta užduoties pobūdžiu.','Esta excepción debería justificarse por el tipo de tarea.','This exception should be justified by the nature of the task.'],['Rezultatus aptartume po dviejų mėnesių.','Revisaríamos los resultados después de dos meses.','We would review results after two months.'],['Esu pasirengęs svarstyti kitą variantą.','Estoy dispuesto a considerar otra opción.','I am willing to consider another option (male speaker).']],
 lesson:['Negotiation can accept a shared goal while disagreeing about the rule used to achieve it.','Distinguish a trial, its exceptions and the criteria for deciding whether it worked.','A qualified recommendation names a limitation without abandoning its central position.'],
 reading:['Įmonės vadovė siūlo, kad visi darbuotojai tris dienas per savaitę dirbtų biure. Jos nuomone, taip būtų lengviau perduoti žinias naujiems kolegoms. Darbuotojų grupė sutinka, kad bendras laikas svarbus, tačiau abejoja, ar vienoda taisyklė tinka visoms užduotims. Analizei ir tekstų rengimui kartais reikia ilgesnio nepertraukiamo darbo, o susitikimus galima sutelkti į sutartas dienas. Grupė siūlo dviejų mėnesių bandymą: dvi bendras dienas biure ir vieną papildomą dieną pagal komandos poreikį. Ji taip pat siūlo vertinti atliktų darbų kokybę, vėlavimus ir naujų kolegų gaunamą pagalbą. Prieštaravimas dėl nevienodų sąlygų pagrįstas: skirtingas grafikas gali atrodyti nesąžiningas. Todėl išimtys turėtų būti aiškiai siejamos su darbo pobūdžiu, o ne su darbuotojo asmeniniais ryšiais.','La directora propone que todo el personal trabaje en la oficina tres días por semana. Considera que así sería más fácil transmitir conocimientos a los nuevos compañeros. Un grupo de empleados acepta la importancia del tiempo compartido, pero duda de que una regla idéntica convenga a todas las tareas. El análisis y la redacción a veces necesitan periodos de concentración, mientras que las reuniones pueden agruparse en días acordados. El grupo propone una prueba de dos meses: dos días comunes en la oficina y otro según las necesidades del equipo. También pide evaluar la calidad del trabajo, los retrasos y el apoyo que reciben los nuevos compañeros. La objeción sobre las condiciones desiguales es razonable: distintos horarios pueden parecer injustos. Por eso, las excepciones deberían depender del tipo de trabajo, no de las relaciones personales de cada empleado.','The director proposes three office days to help transfer knowledge to new staff. Employees accept shared time but question a uniform rule. They propose a two-month trial of two common office days plus one according to team need, evaluated by quality, delays and support for newcomers. They acknowledge a fairness objection and propose task-based, transparent exceptions rather than personal favouritism.'],
 listen:['Norėčiau pasiūlyti kompromisą dėl darbo grafiko. Dvi bendros dienos suteiktų pakankamai laiko daugumai susitikimų, bet naujiems darbuotojams pirmą mėnesį reikėtų daugiau pagalbos vietoje. Siūlau jiems ir jų mentoriams sutarti dėl trečios dienos. Tai nebūtų nuolatinė taisyklė visai komandai. Suprantu susirūpinimą dėl išimčių, todėl jų priežastis reikėtų užrašyti ir reguliariai peržiūrėti. Bandymo pabaigoje nepakaktų suskaičiuoti, kiek žmonių atėjo į biurą. Reikėtų paklausti, ar nauji kolegos laiku gavo atsakymus, ar susitikimai padėjo priimti sprendimus ir ar liko laiko susikaupti. Jei pagalbos trūktų, grafiką reikėtų koreguoti, net jeigu dauguma darbuotojų juo būtų patenkinti.','Quisiera proponer un acuerdo sobre los horarios. Dos días comunes darían tiempo para la mayoría de las reuniones, pero el personal nuevo podría necesitar más apoyo presencial durante el primer mes. Sugiero que cada persona nueva acuerde un tercer día con su mentor. No sería una regla permanente para todo el equipo. Entiendo la preocupación por las excepciones; sus motivos deberían quedar por escrito y revisarse regularmente. Al terminar la prueba no bastaría contar cuántas personas asistieron. Habría que preguntar si los nuevos compañeros recibieron respuestas a tiempo, si las reuniones permitieron tomar decisiones y si quedó tiempo para concentrarse. Si faltara apoyo, habría que ajustar el horario aunque la mayoría estuviera satisfecha.','The speaker proposes a third day for newcomers and mentors during the first month, not permanently for everyone. Reasons for exceptions should be documented and reviewed. Attendance alone is insufficient: evaluate timely answers, useful decisions and concentration time. Insufficient support should trigger changes even if the majority is satisfied.'],
 readQ:[['What common goal do the two sides accept?',['Time together supports collaboration','Everyone must keep exactly the same schedule','Attendance alone proves quality'],0],['How should exceptions be justified?',['Through personal relationships','By the nature of the work','By whoever complains most'],1],['Which evaluation matches the group’s proposal?',['Only count office visits','Only measure staff age','Assess quality, delays and support'],2]],
 hearQ:[['Who would initially agree a third day?',['Every employee permanently','New staff and their mentors','Only the director'],1],['Why document exceptions?',['To make their reasons transparent and reviewable','To prevent any future adjustment','To replace the trial with a permanent rule'],0],['What could justify changing a popular schedule?',['A high attendance total alone','The existence of meeting rooms','Inadequate support for newcomers'],2]],
 turns:[['Kokį grafiką rekomenduotumėte mūsų komandai?','¿Qué horario recomendaría para nuestro equipo?','Which schedule would you recommend?','Propose a model and explain how it addresses two needs.'],['Ar tokios išimtys nebus nesąžiningos kitiems?','¿No serían injustas esas excepciones para los demás?','Would those exceptions not be unfair to others?','Acknowledge the fairness concern and propose a transparent condition.'],['Kada turėtume keisti susitarimą?','¿Cuándo deberíamos cambiar el acuerdo?','When should we change the agreement?','Give a review point and a concrete trigger for adjustment.']],
 production:['Recommend a working arrangement while balancing collaboration, concentration and fairness.',['Develop a clear recommendation.','Address a credible objection.','Explain how the trial will be judged and revised.']],
 mediation:'Brief a new team member on the difference between the written general trial and the spoken temporary mentoring exception.',
 project:{title:'A negotiated proposal',audience:'A manager and employee representatives',brief:'Write a proposal for a working arrangement, showing conditions and a review process.',goals:['Balance two legitimate needs.','Address fairness and explain any exception.','Give evaluation criteria and a revision condition.'],range:[190,280]}},
{id:'B2-media',band:'B2',theme:'Read a report critically',focus:'Distinguish a reported association from a causal claim and communicate a correction fairly.',
 phrases:[['Antraštė supaprastina tyrimo išvadą.','El titular simplifica la conclusión del estudio.','The headline simplifies the study’s conclusion.'],['Tai rodo ryšį, bet ne priežastį.','Esto muestra una relación, no una causa.','This shows an association, not a cause.'],['Apklausoje dalyvavo tik savanoriai.','En la encuesta solo participaron voluntarios.','Only volunteers took part in the survey.'],['Galimi ir kiti paaiškinimai.','También son posibles otras explicaciones.','Other explanations are possible.'],['Reikėtų patikrinti pirminį šaltinį.','Habría que consultar la fuente original.','The original source should be checked.'],['Šis teiginys yra platesnis už pateiktus duomenis.','Esta afirmación va más allá de los datos presentados.','This claim goes beyond the data presented.'],['Vis dėlto rezultatas gali būti naudingas.','Aun así, el resultado puede ser útil.','Nevertheless, the result may be useful.'],['Pataisymas turėtų būti aiškiai matomas.','La corrección debería ser claramente visible.','The correction should be clearly visible.']],
 lesson:['An association describes how things vary together; it does not by itself establish what caused what.','A limited sample can still provide useful information, but may not represent everyone.','A fair correction preserves what the evidence supports instead of reversing an overstatement into an opposite certainty.'],
 reading:['Mokomojo naujienų portalo antraštė skelbia: „Pasivaikščiojimai daro žmones laimingesnius.“ Straipsnyje aprašoma savanorių apklausa: žmonės, kurie dažniau vaikščiojo, savo savijautą vertino geriau. Tačiau apklausa neparodė, ar būtent pasivaikščiojimai lėmė geresnę savijautą. Galbūt geriau besijaučiantys žmonės dažniau išeina iš namų, o gal abi aplinkybes veikia kiti veiksniai. Be to, dalyviai patys pasirinko atsakyti į klausimus. Tai nereiškia, kad apklausa bevertė. Ji gali paskatinti aiškiau apibrėžtą tyrimą ir parodyti, kokius klausimus verta užduoti. Vis dėlto straipsnyje reikėtų atskirti nustatytą ryšį nuo priežastinio paaiškinimo. Tikslesnė antraštė informuotų apie apklausos rezultatą, neapsimesdama, kad galutinis paaiškinimas jau rastas.','El titular de un portal de noticias ficticio anuncia: «Caminar hace más feliz a la gente». El artículo describe una encuesta voluntaria: quienes caminaban más a menudo valoraban mejor su bienestar. Sin embargo, la encuesta no mostró que caminar causara esa diferencia. Quizá las personas que ya se sienten mejor salen más de casa, o quizá otros factores influyen en ambas cosas. Además, los participantes decidieron por su cuenta responder. Eso no vuelve inútil la encuesta. Puede sugerir una investigación más precisa e indicar qué preguntas conviene formular. Aun así, el artículo debería distinguir la relación observada de una explicación causal. Un titular más exacto comunicaría el resultado de la encuesta sin fingir que ya existe una explicación definitiva.','A fictional headline claims walking causes happiness, but its voluntary survey shows only an association between walking frequency and reported wellbeing. Reverse causation and other factors remain possible; volunteers may be unrepresentative. The survey can still suggest further questions. A fair headline should report the association without claiming established causation.'],
 listen:['Mūsų redakcija pakeitė antraštę apie pasivaikščiojimus. Naujoji versija pabrėžia, kad kalbame apie apklausą, o ne apie įrodytą poveikį. Prie straipsnio pridėjome paaiškinimą, kodėl ankstesnė formuluotė buvo per stipri. Kai kurie skaitytojai siūlė straipsnį visai pašalinti, tačiau nusprendėme išsaugoti tekstą su aiškiai matomu pataisymu. Taip galima suprasti ir pirminę klaidą, ir jos taisymą. Ateityje prieš skelbdami priežastinį teiginį turėsime patikrinti, kokio pobūdžio duomenimis jis remiasi. Tai negarantuos, kad klaidų nebebus, bet suteiks konkretų būdą sumažinti panašių klaidų tikimybę.','La redacción cambió el titular sobre las caminatas. La nueva versión deja claro que hablamos de una encuesta, no de un efecto demostrado. Añadimos una explicación de por qué la formulación anterior era demasiado fuerte. Algunos lectores propusieron eliminar el artículo, pero decidimos conservarlo con una corrección visible. Así se puede entender tanto el error original como su rectificación. En adelante, antes de publicar una afirmación causal, tendremos que comprobar qué tipo de datos la respalda. Eso no garantizará que nunca cometamos errores, pero ofrece una medida concreta para reducir la posibilidad de repetirlos.','Editors revised the headline, explained the overstatement and retained the article with a visible correction rather than deleting it. They will check the type of evidence behind future causal claims. This reduces risk but does not guarantee error-free reporting.'],
 readQ:[['What does the survey directly establish?',['An association in volunteers’ responses','A universal cause of happiness','The absence of any other explanation'],0],['Why does self-selection matter?',['It makes every answer false','The sample may not represent everyone','It proves walking has no effect'],1],['Which correction preserves the evidence?',['Walking never affects wellbeing','All surveys must be removed','Survey respondents who walk more report better wellbeing'],2]],
 hearQ:[['What did the editors decide?',['Delete all evidence of the error','Retain the article with a visible correction','Keep the original headline unchanged'],1],['Why explain the old wording?',['To make the error and correction understandable','To claim the original headline was precise','To blame all readers'],0],['What does the new checking procedure promise?',['Perfect accuracy forever','Proof of a causal effect','A concrete reduction in a recurring risk'],2]],
 turns:[['Ką iš tikrųjų parodė ši apklausa?','¿Qué mostró realmente esta encuesta?','What did this survey actually show?','State the association without turning it into a cause.'],['Ar tai reiškia, kad visas straipsnis bevertis?','¿Significa eso que todo el artículo carece de valor?','Does that mean the whole article is worthless?','Correct the overstatement while explaining a legitimate use.'],['Kaip turėtume paskelbti pataisymą?','¿Cómo deberíamos publicar la corrección?','How should we publish the correction?','Propose a transparent correction and a preventive step.']],
 production:['Explain a misleading report and propose a fair correction.',['Separate the reported finding from the causal claim.','Acknowledge a meaningful limitation.','Preserve useful information while recommending a correction.']],
 mediation:'Explain to a reader both why the original headline was misleading and why the editors kept the corrected article.',
 project:{title:'A transparent correction',audience:'Readers of a fictional news site',brief:'Write a correction note that explains an overstatement without inventing the opposite conclusion.',goals:['Identify the unsupported claim.','State what the evidence actually supports.','Explain the correction and one concrete editorial safeguard.'],range:[180,270]}}
,{id:'C1-academic',band:'C1',theme:'Evaluate competing explanations',focus:'Interpret the limits of a study, compare explanations and adapt findings for a non-specialist audience.',
 phrases:[['Duomenys suderinami su keliais paaiškinimais.','Los datos son compatibles con varias explicaciones.','The data are compatible with several explanations.'],['Imties sudėtis riboja apibendrinimą.','La composición de la muestra limita la generalización.','The sample’s composition limits generalisation.'],['Neatmestina ir atrankos įtaka.','Tampoco puede descartarse un efecto de selección.','A selection effect cannot be ruled out either.'],['Šis skirtumas nebūtinai yra programos poveikis.','Esta diferencia no es necesariamente un efecto del programa.','This difference is not necessarily an effect of the programme.'],['Reikėtų palyginamos grupės.','Haría falta un grupo comparable.','A comparable group would be needed.'],['Svarbu nurodyti, ko tyrimas neatskleidžia.','Es importante señalar qué no permite saber el estudio.','It is important to state what the study does not establish.'],['Praktinė rekomendacija turi būti sąlyginė.','La recomendación práctica debe ser condicional.','The practical recommendation must be conditional.'],['Papildomi duomenys galėtų pakeisti vertinimą.','Otros datos podrían modificar la evaluación.','Additional data could change the evaluation.']],
 lesson:['Distinguish an observed improvement, an explanation of its cause and a recommendation about future action.','Consider whether people chose to participate and what a suitable comparison would require.','For a non-specialist listener, simplify terminology while preserving the uncertainty that changes the decision.'],
 reading:['Išgalvoto universiteto ataskaitoje aprašoma nauja studentų konsultavimo programa. Joje dalyvavę studentai semestro pabaigoje dažniau pateikė darbus laiku negu programoje nedalyvavę studentai. Ataskaitos santraukoje tai pristatoma kaip programos veiksmingumo ženklas. Toks aiškinimas galimas, tačiau vien pateikto palyginimo jam pagrįsti nepakanka. Studentai patys rinkosi, ar dalyvauti, o jų ankstesni darbo įpročiai nebuvo lyginti. Todėl negalima atmesti, kad programą dažniau rinkosi jau labiau motyvuoti studentai. Kita vertus, ši atrankos problema savaime neįrodo, kad konsultacijos nieko nepakeitė. Ji nurodo, kokia abejonė lieka neatsakyta. Tikslesniam vertinimui reikėtų palyginti panašią pradinę padėtį turinčias grupes ir stebėti, kaip jų rezultatai keičiasi laikui bėgant. Praktinis sprendimas taip pat neturi apsiriboti klausimu „plėsti ar nutraukti“. Galima tęsti ribotos apimties programą, kartu tikslinant vertinimą ir viešai nurodant išvadų ribas. Tokia rekomendacija pripažįsta ir galimą naudą, ir pareigą jos nepateikti kaip jau galutinai nustatyto poveikio.','El informe de una universidad ficticia describe un nuevo programa de asesoría estudiantil. Al terminar el semestre, quienes participaron entregaron sus trabajos puntualmente con mayor frecuencia que quienes no participaron. El resumen presenta la diferencia como indicio de la eficacia del programa. La explicación es posible, pero la comparación descrita no basta para establecerla. Los estudiantes decidieron si inscribirse y no se compararon sus hábitos de trabajo anteriores. Por tanto, no puede descartarse que el programa atrajera a personas que ya estaban más motivadas. A su vez, ese problema de selección tampoco demuestra que la asesoría no haya cambiado nada. Señala una incertidumbre que sigue abierta. Una evaluación más precisa necesitaría comparar grupos con condiciones iniciales semejantes y observar cómo evolucionan sus resultados. La decisión práctica tampoco tiene por qué reducirse a ampliar o cancelar. Se podría mantener una versión limitada mientras se mejora la evaluación y se comunican sus límites. Esa recomendación reconoce un beneficio posible sin presentarlo como un efecto ya establecido de forma definitiva.','A fictional university reports that voluntary programme participants submit work on time more often. This is compatible with an effect, but participants’ prior habits were not compared and selection by motivation remains possible. That limitation does not prove ineffectiveness. Better comparison groups and change over time are needed. A limited continuation with improved evaluation is a conditional alternative to immediate expansion or cancellation.'],
 listen:['Norėčiau pataisyti dvi priešingas mūsų ataskaitos interpretacijas. Vieni kolegos teigia, kad programa jau įrodė savo veiksmingumą. Kiti sako, kad dėl savanoriško dalyvavimo visi rezultatai beprasmiški. Abi išvados per stiprios. Matome skirtumą tarp grupių, bet dar nepakankamai suprantame jo kilmę. Kitą semestrą siūlome prieš programos pradžią surinkti informaciją apie studentų ankstesnius įpročius ir numatyti palyginimą su panašioje padėtyje esančiais studentais. Taip pat turėtume kalbėtis su tais, kurie norėjo dalyvauti, bet negalėjo atvykti sutartu laiku. Jų patirtis padėtų atskirti susidomėjimo stoką nuo praktinių kliūčių. Iki tol rekomenduočiau programą tęsti, tačiau viešai vartoti žodžius „perspektyvus rezultatas“, o ne „įrodytas poveikis“. Šis skirtumas svarbus ne vien akademiniam tikslumui: nuo jo priklauso, kaip atsakingai pagrindžiame sprendimą skirti daugiau išteklių.','Quisiera corregir dos interpretaciones opuestas de nuestro informe. Algunos colegas afirman que el programa ya demostró su eficacia. Otros sostienen que la participación voluntaria vuelve irrelevantes todos los resultados. Ambas conclusiones son excesivas. Observamos una diferencia entre grupos, pero todavía no entendemos suficientemente su origen. El próximo semestre proponemos recoger información sobre los hábitos anteriores y prever una comparación con estudiantes en condiciones semejantes. También deberíamos hablar con quienes querían participar pero no podían asistir en el horario disponible. Su experiencia ayudaría a distinguir la falta de interés de las barreras prácticas. Mientras tanto, recomendaría continuar el programa, pero hablar públicamente de un resultado prometedor, no de un efecto demostrado. La distinción no es solo académica: afecta a la responsabilidad con que justificamos destinar más recursos.','The speaker rejects both proven efficacy and total meaninglessness. Next term should measure prior habits, use comparable students and consult interested people prevented by scheduling. Until then, continue conditionally and say “promising result”, not “proven effect”, especially when justifying resources.'],
 readQ:[['Which uncertainty is central?',['Whether prior motivation explains some of the difference','Whether the university exists in the exercise','Whether punctuality was mentioned'],0],['What does the selection limitation establish?',['That the programme certainly failed','That the causal interpretation remains uncertain','That no comparison can ever help'],1],['Which recommendation reflects the text?',['Expand without further evaluation','Cancel because all results are worthless','Continue on a limited basis while improving evaluation'],2]],
 hearQ:[['Why consult people unable to attend?',['To prove they lacked interest','To distinguish interest from practical barriers','To exclude them from future analysis'],1],['Which wording is recommended now?',['A promising result','A proven effect','An entirely meaningless result'],0],['Why does wording matter practically?',['It removes the need for data','It guarantees the programme works','It affects the justification for allocating resources'],2]],
 turns:[['Kokią išvadą iš šių rezultatų galima daryti pagrįstai?','¿Qué conclusión permiten sostener estos resultados?','What conclusion is warranted?','State the observed result and bound the interpretation.'],['Ar atrankos problema nereiškia, kad programą reikia nutraukti?','¿El problema de selección no obliga a cancelar el programa?','Does the selection problem require cancellation?','Distinguish an unresolved cause from demonstrated lack of benefit.'],['Paaiškinkite rekomendaciją studentų atstovams be metodinių terminų.','Explique la recomendación a representantes estudiantiles sin tecnicismos.','Explain the recommendation to student representatives without technical jargon.','Adapt the language while preserving the uncertainty and next step.']],
 production:['Present a qualified evaluation of the fictional programme for a university committee.',['Distinguish findings from competing explanations.','Specify what a better comparison would address.','Make a practical recommendation with a condition.']],
 mediation:'Explain to a student representative why the programme can be promising without its causal effect having been demonstrated.',
 project:{title:'An evidence briefing',audience:'A university committee',brief:'Write a decision briefing integrating the report and spoken methodological update.',goals:['Separate observation, explanation and recommendation.','Explain the main limitation in accessible language.','State a conditional decision and the evidence needed next.'],range:[250,370]}},
{id:'C1-culture',band:'C1',theme:'Interpret a cultural dispute',focus:'Identify competing values, interpret tone and explain a dispute without flattening its positions.',
 phrases:[['Ginčas kyla dėl skirtingo autentiškumo supratimo.','La disputa nace de distintas ideas de autenticidad.','The dispute arises from different understandings of authenticity.'],['Viena pozicija pabrėžia tęstinumą.','Una postura subraya la continuidad.','One position emphasises continuity.'],['Kita pozicija teikia pirmenybę dalyvavimui.','La otra da prioridad a la participación.','The other gives priority to participation.'],['Būtų netikslu tai vadinti visišku atmetimu.','Sería inexacto llamarlo un rechazo absoluto.','It would be inaccurate to call it complete rejection.'],['Formuluotė leidžia numanyti abejonę.','La formulación deja entrever una reserva.','The wording suggests a reservation.'],['Reikia atskirti kritiką nuo draudimo reikalavimo.','Hay que distinguir la crítica de una exigencia de prohibición.','Criticism must be distinguished from a demand for prohibition.'],['Bendras tikslas neužtikrina vienodo sprendimo.','Un objetivo compartido no garantiza una misma solución.','A shared goal does not guarantee the same solution.'],['Paaiškinimas turėtų išsaugoti šį skirtumą.','La explicación debería conservar esa distinción.','The explanation should preserve that distinction.']],
 lesson:['A cultural disagreement may concern which value should guide a decision, rather than a dispute about basic facts.','Interpret qualifying phrases before assigning an absolute position to a speaker.','Adapting a dispute for visitors requires explaining the stakes, not merely naming two opposing camps.'],
 reading:['Išgalvoto miesto muziejus siūlo seną amatų parodą papildyti lankytojų dirbtuvėmis. Kuratorė teigia, kad galimybė išbandyti paprastą techniką padėtų suprasti, kiek įgūdžių reikia meistro darbui. Amatininkų atstovas neprieštarauja lankytojų dalyvavimui, tačiau abejoja, ar trumpa pramoga nebus pristatyta kaip viso amato pažinimas. Jo žodžiais, „prisiliesti prie medžiagos dar nereiškia suprasti tradiciją“. Šią pastabą būtų netikslu laikyti reikalavimu uždrausti dirbtuves. Ji veikiau kelia klausimą, kaip atskirti pirmą pažintį nuo įgytos kompetencijos. Abi pusės nori, kad amatas liktų gyvas, bet skirtingai įsivaizduoja, kas tam būtina. Kuratorė pabrėžia atvirumą naujiems dalyviams, o atstovas – tęstinumą ir mokymosi trukmę. Galimas sprendimas būtų dirbtuves aiškiai pristatyti kaip įvadą, suteikti žodį patiems meistrams ir parodyti, kaip atrodo ilgesnis mokymosi kelias. Taip lankytojų įtraukimas nebūtų priešpriešinamas tradicijos sudėtingumui.','El museo de una ciudad ficticia propone añadir talleres para visitantes a una exposición de oficios tradicionales. La curadora sostiene que probar una técnica sencilla ayudaría a comprender la habilidad del artesano. Un representante de los maestros no rechaza la participación, pero duda de que una actividad breve se presente como conocimiento completo del oficio. En sus palabras, «tocar el material no equivale a comprender la tradición». Sería inexacto interpretar la observación como una exigencia de prohibir los talleres. Más bien pregunta cómo distinguir un primer acercamiento de una competencia adquirida. Ambas partes desean mantener vivo el oficio, pero imaginan de manera distinta lo que eso requiere. La curadora destaca la apertura a nuevos participantes; el representante, la continuidad y la duración del aprendizaje. Una solución posible sería presentar los talleres como una introducción, dar voz a los maestros y mostrar cómo sería un aprendizaje prolongado. Así, la participación del público no tendría que oponerse a la complejidad de la tradición.','A fictional museum proposes hands-on craft workshops. The curator sees participation as a route to appreciating skill. A craft representative accepts participation but worries that a brief activity will be presented as complete knowledge. His criticism is not a ban request. Both want a living craft, prioritising openness and sustained transmission differently. Introductory labelling, artisans’ voices and an explanation of longer learning could connect the goals.'],
 listen:['Apie muziejaus dirbtuves norėčiau kalbėti ne kaip apie kompromisą tarp pažangos ir užsispyrimo. Toks apibūdinimas jau iš anksto vieną pusę paverčia kliūtimi. Amatininkų pastaba verčia klausti, ką žadame lankytojui. Jei sakome „per valandą tapsite meistru“, sukuriame klaidingą įspūdį. Jei kviečiame patirti pirmą mokymosi žingsnį, tas pats užsiėmimas įgauna kitą prasmę. Vis dėlto vien užrašo pakeisti nepakaks. Meistrai turėtų dalyvauti sprendžiant, kokią techniką rodyti ir kaip paaiškinti jos ryšį su platesne tradicija. Taip pat reikėtų išgirsti naujus lankytojus: ar jie po dirbtuvių geriau supranta amato sudėtingumą, ar tik prisimena malonią veiklą? Atsakymas padėtų vertinti ne vien renginio populiarumą, bet ir jo mokomąją vertę.','Quisiera hablar de los talleres sin describirlos como un compromiso entre progreso y terquedad. Esa etiqueta convierte de antemano a una parte en obstáculo. La observación de los artesanos nos obliga a preguntar qué prometemos al visitante. Si anunciamos que será maestro en una hora, creamos una impresión engañosa. Si lo invitamos a experimentar un primer paso de aprendizaje, la misma actividad adquiere otro sentido. Sin embargo, no basta cambiar el letrero. Los maestros deberían participar en decidir qué técnica mostrar y cómo explicar su relación con la tradición. También habría que escuchar a los visitantes nuevos: ¿comprenden mejor la complejidad del oficio o solo recuerdan una actividad agradable? Esa respuesta permitiría evaluar el valor educativo, además de la popularidad del evento.','The speaker rejects framing the dispute as progress versus stubbornness because it prejudges one side. The promise made to visitors matters, but changing a label alone is insufficient. Artisans should help select and explain techniques. Evaluate whether visitors understand the craft’s complexity, not only whether they enjoyed the activity.'],
 readQ:[['What does the representative mainly question?',['Whether an introduction is being sold as complete knowledge','Whether visitors should ever enter a museum','Whether the craft exists'],0],['What goal do both sides share?',['Making every visitor a master in an hour','Keeping the craft alive','Removing artisans from the exhibition'],1],['Which proposal responds to both values?',['Ban all participation','Ignore the length of learning','Offer clearly introductory workshops with artisans’ involvement'],2]],
 hearQ:[['Why reject “progress versus stubbornness”?',['It is too long for a label','It prejudges one side as an obstacle','It proves the activity failed'],1],['What is needed beyond a new label?',['Artisans’ participation in design and explanation','A promise of mastery in one hour','Removing all visitor feedback'],0],['What should evaluation examine?',['Only ticket sales','Only whether visitors smiled','Understanding as well as enjoyment'],2]],
 turns:[['Kokia iš tikrųjų yra šio ginčo esmė?','¿Cuál es realmente el centro de esta disputa?','What is the real issue in the dispute?','Explain the values without portraying one side as anti-participation.'],['Ar pakaktų tiesiog pakeisti dirbtuvių pavadinimą?','¿Bastaría con cambiar el nombre del taller?','Would changing the workshop’s name be enough?','Distinguish presentation from substantive involvement.'],['Kaip tai paaiškintumėte muziejaus lankytojams?','¿Cómo se lo explicaría a los visitantes?','How would you explain this to visitors?','Give an accessible introduction that preserves the distinction between trying and mastering.']],
 production:['Explain the cultural dispute and recommend an educational response.',['Represent both values fairly.','Interpret the representative’s qualification accurately.','Connect the recommendation to an educational aim.']],
 mediation:'Prepare a visitor briefing that explains why introductory participation can be valuable without being equivalent to mastery.',
 project:{title:'A museum interpretation note',audience:'Museum visitors and workshop organisers',brief:'Write an interpretation note explaining the purpose and limits of an introductory craft activity.',goals:['Clarify what participation offers.','Preserve the role of extended learning and practitioners.','Suggest how educational value should be evaluated.'],range:[250,370]}}
,{id:'C2-science',band:'C2',theme:'Communicate uncertainty precisely',focus:'Reconcile provisional evidence, competing decision standards and the implications of a public formulation.',
 phrases:[['Neapibrėžtumas nėra nei įrodymas, nei paneigimas.','La incertidumbre no constituye ni una prueba ni una refutación.','Uncertainty is neither proof nor refutation.'],['Nesant duomenų, negalima teigti, kad poveikio nėra.','La ausencia de datos no permite afirmar que no exista un efecto.','A lack of data does not establish the absence of an effect.'],['Sprendimo slenkstis priklauso nuo pasekmių.','El umbral para decidir depende de las consecuencias.','The decision threshold depends on the consequences.'],['Atsargumo argumentas taip pat turi būti pagrįstas.','El argumento de precaución también necesita justificación.','An argument for caution also requires justification.'],['Ši išlyga keičia teiginio apimtį.','Esta salvedad modifica el alcance de la afirmación.','This qualification changes the claim’s scope.'],['Būtų klaidinga sutapatinti šiuos du klausimus.','Sería erróneo equiparar estas dos preguntas.','It would be mistaken to equate these two questions.'],['Rekomendacija peržiūrėtina, jei pasikeistų...','La recomendación debería revisarse si cambiara...','The recommendation should be reviewed if...'],['Vieša formuluotė neturėtų slėpti pasirinkto kriterijaus.','La formulación pública no debería ocultar el criterio elegido.','The public wording should not conceal the criterion chosen.']],
 lesson:['Separate what evidence establishes from what decision-makers regard as enough to act.','Neither certainty nor caution should be smuggled into a conclusion by an ambiguous phrase.','A precise public explanation can be short while retaining the condition that would change the recommendation.'],
 reading:['Išgalvota miesto komisija svarsto triukšmą mažinančios dangos bandymą. Trumpame bandomajame ruože matavimai rodo mažesnį triukšmą, tačiau ilgalaikis dangos patvarumas dar neįvertintas. Viena komisijos narė siūlo projektą plėsti, nes nėra duomenų, kad danga būtų nepatvari. Kitas narys reikalauja bandymą nutraukti, kol bus visiškas tikrumas dėl visų pasekmių. Abi formuluotės nuslepia sprendimo kriterijų. Pirmoji nežinojimą paverčia palankiu įrodymu; antroji nustato slenkstį, kurio galbūt neįmanoma pasiekti jokiam praktiniam sprendimui. Tai nereiškia, kad abu pasiūlymai vienodai nepagrįsti ar kad vienintelė teisinga išeitis yra vidurys. Reikia atskirai įvertinti galimą naudą, negrįžtamų pasekmių riziką, tolesnio bandymo kainą ir sprendimo atidėjimo poveikį. Jei plėtra būtų ribota ir lengvai pakeičiama, mažesnis tikrumas galėtų būti priimtinas negu negrįžtamam sprendimui. Tačiau šį pasirinkimą reikėtų įvardyti, o ne pateikti kaip savaime iš duomenų išplaukiančią būtinybę. Pagrįsta rekomendacija galėtų siūlyti kontroliuojamą papildomą bandymą, iš anksto numatant patvarumo vertinimą ir nutraukimo sąlygą. Viešame paaiškinime turėtų likti aišku, kad triukšmo sumažėjimas jau stebėtas, o ilgalaikis patvarumas vis dar tiriamas.','Una comisión municipal ficticia estudia una superficie destinada a reducir el ruido. Las mediciones de un tramo piloto muestran menos ruido, pero aún no se ha evaluado su durabilidad a largo plazo. Una integrante propone ampliarlo porque no hay datos que indiquen que sea poco durable. Otro exige suspenderlo hasta tener certeza total sobre todas las consecuencias. Ambas formulaciones ocultan un criterio de decisión. La primera convierte el desconocimiento en evidencia favorable; la segunda fija un umbral que quizá ningún proyecto práctico pueda alcanzar. Esto no implica que las dos propuestas estén igualmente justificadas ni que el punto medio sea necesariamente correcto. Hay que valorar por separado el beneficio posible, el riesgo de consecuencias irreversibles, el costo de seguir probando y los efectos de aplazar la decisión. Una ampliación limitada y reversible podría admitir más incertidumbre que una decisión irreversible. Pero ese criterio debería hacerse explícito, en lugar de presentarse como una necesidad que los datos dictan por sí solos. Una recomendación razonada podría proponer otra prueba controlada, con evaluación de durabilidad y condiciones de suspensión establecidas de antemano. La explicación pública debería conservar una distinción fundamental: la reducción del ruido ya se observó; la durabilidad sigue investigándose.','A fictional surface trial shows noise reduction but has not established long-term durability. Expansion based on no contrary data mistakes ignorance for favourable evidence; a demand for total certainty may impose an unattainable threshold. This does not make both positions equivalent or establish a midpoint. Decisions should weigh benefits, reversibility, further testing and delay. A controlled extension with durability measures and stopping conditions can distinguish observed noise effects from unresolved durability.'],
 listen:['Kai visuomenei sakome, kad bandymas pasiteisino, turime iš karto paaiškinti, kokiu požiūriu. Triukšmo matavimai palankūs, bet jie neatsako į klausimą, kaip danga atrodys po kelių metų. Taip pat nenorėčiau, kad žodis eksperimentas būtų vartojamas kaip savaiminis kaltinimas neatsakingumu. Ribotas ir grįžtamas bandymas gali būti būdas elgtis atsakingai, jeigu jo ribos ir stabdymo sąlygos tikros, o ne vien deklaruojamos. Todėl siūlau ne tik numatyti patikrinimą po žiemos, bet ir iš anksto pasakyti, kas turės teisę sustabdyti plėtrą, jei atsiras pažeidimų. Vien techninio rodiklio neužtenka, jei niekas neįsipareigoja pagal jį veikti. Kita vertus, būtų klaidinga iš galimybės sustabdyti bandymą daryti išvadą, kad bet kokia jo pasekmė lengvai atitaisoma. Būtent todėl rekomendacija turėtų nurodyti ir tas pasekmes, kurių grįžtamumu abejojame. Mano pozicija yra sąlyginė: tęsti mažos apimties bandymą, bet nevadinti jo bendru technologijos patvirtinimu.','Cuando decimos al público que la prueba funcionó, debemos aclarar en qué sentido. Las mediciones de ruido son favorables, pero no responden cómo estará la superficie dentro de varios años. Tampoco quisiera que la palabra experimento se utilizara como acusación automática de irresponsabilidad. Una prueba limitada y reversible puede ser responsable si sus límites y condiciones de suspensión son reales, no meramente declarativos. Por eso propongo no solo una revisión después del invierno, sino definir de antemano quién podrá detener la ampliación si aparecen daños. Un indicador técnico sirve de poco si nadie se compromete a actuar conforme a él. Sin embargo, sería erróneo inferir que poder suspender una prueba hace fácilmente reparable cualquiera de sus consecuencias. La recomendación debe señalar también aquellas cuya reversibilidad sigue siendo incierta. Mi postura es condicional: continuar a pequeña escala, sin presentarlo como una validación general de la tecnología.','The speaker qualifies success as noise reduction, rejects treating experimentation as automatically irresponsible, and requires authority to act on stopping criteria after winter. Stopping a trial does not guarantee every consequence is reversible. They support a small conditional continuation, not general technological validation.'],
 readQ:[['What is wrong with the no-contrary-data argument?',['It treats an unresolved question as favourable evidence','It establishes long-term durability','It rejects the noise measurements'],0],['What follows from criticising both formulations?',['The midpoint is necessarily correct','Their criteria should be examined without assuming equivalence','Every decision must wait for absolute certainty'],1],['Which public statement preserves the distinction?',['The technology is fully validated','Durability has been disproved','Noise fell in the pilot; durability is still under evaluation'],2]],
 hearQ:[['Why identify who can halt expansion?',['To replace evidence with popularity','To connect the criterion to actual authority and action','To guarantee that damage is impossible'],1],['Which inference does the speaker reject?',['A stoppable trial necessarily has only reversible consequences','A limited trial can sometimes be responsible','Noise measurement and durability answer different questions'],0],['What is the speaker’s recommendation?',['Unconditional expansion','Permanent suspension of every experiment','Small-scale continuation with explicit conditions'],2]],
 turns:[['Jei žala neįrodyta, kodėl dar reikia sąlygų?','Si no se ha demostrado un daño, ¿por qué exigir condiciones?','If harm has not been proved, why require conditions?','Distinguish lack of evidence from evidence of absence without asserting unobserved harm.'],['Ar atsargumas čia nėra tik pažangos stabdymas?','¿La precaución no es aquí una forma de frenar el progreso?','Is caution merely obstructing progress?','Explain a proportionate decision standard, considering delay as well as risk.'],['Pateikite vieno sakinio rekomendaciją tarybai.','Formule una recomendación de una sola frase para el consejo.','Give the council a one-sentence recommendation.','Preserve the conditional decision, unresolved question and review trigger.']],
 production:['Present a precise recommendation about the fictional trial under competing demands for action and certainty.',['Separate evidence, uncertainty and decision standards.','Engage the strongest objection without false equivalence.','State an actionable condition and what would change the recommendation.']],
 mediation:'Explain to a public audience how a pilot can show a benefit while leaving a separate question unresolved, and why stopping authority matters.',
 project:{title:'A precise public recommendation',audience:'A municipal council and interested residents',brief:'Write a recommendation distinguishing observed benefit from unresolved durability, making its decision standard explicit.',goals:['Avoid unsupported assurance and an undefined demand for certainty.','Explain reversibility, delay and accountability separately.','Give a conditional decision and a meaningful review trigger.'],range:[320,450]}}
,{id:'C2-literature',band:'C2',theme:'Interpret voice and ambiguity',focus:'Distinguish a narrator’s wording from an authorial judgement and defend an interpretation without closing legitimate ambiguity.',
 phrases:[['Pasakotojo žodžiai nebūtinai išreiškia autoriaus poziciją.','Las palabras del narrador no expresan necesariamente la postura del autor.','The narrator’s words do not necessarily express the author’s position.'],['Ši detalė leidžia abejoti pirmuoju įspūdžiu.','Este detalle permite cuestionar la primera impresión.','This detail invites doubt about the first impression.'],['Ironija kyla iš neatitikimo.','La ironía nace de una discrepancia.','The irony arises from a discrepancy.'],['Tekstas nepateikia galutinio atsakymo.','El texto no ofrece una respuesta definitiva.','The text does not provide a definitive answer.'],['Interpretaciją reikėtų pagrįsti formuluote.','La interpretación debe apoyarse en la formulación.','The interpretation should be supported by the wording.'],['Dviprasmybė nėra bet kokio aiškinimo pateisinimas.','La ambigüedad no justifica cualquier lectura.','Ambiguity does not justify every reading.'],['Šis perskaitymas įtikinamas tiek, kiek...','Esta lectura resulta convincente en la medida en que...','This reading is convincing insofar as...'],['Alternatyvi interpretacija išryškina...','Una interpretación alternativa pone de relieve...','An alternative interpretation highlights...']],
 lesson:['Distinguish the narrator’s explicit self-description from details that complicate it.','Support a possible irony with the relation between wording and action, not merely the word “ironic”.','Acknowledge an alternative reading, then explain which details make one interpretation stronger.'],
 reading:['„Aš niekada nesikišu į kitų reikalus“, – pasakė kaimynas ir dar kartą patikrino, kas užėjo į priešais esantį butą. Užrašų knygelę jis vadino atminties pagalbininke: juk žmogus negali visko prisiminti. Kai laiptinėje kas nors paklausdavo, kodėl jam reikia žinoti svetimų svečių vardus, jis tik šyptelėdavo: „Tvarka visiems naudinga.“ Vieną vakarą į duris pasibeldė nauja gyventoja. Ji paklausė, ar jis matęs jos tėvą, kuris išėjo pasivaikščioti ir negrįžo sutartu laiku. Kaimynas iš karto pasakė, kuria kryptimi vyras nuėjo ir kokį paltą vilkėjo. Gyventoja padėkojo. Uždarydamas duris jis patenkintas pažvelgė į knygelę, bet pirmą kartą tos dienos įrašo neužbaigė. Ši originali ištrauka neleidžia veikėjo paprastai padalyti į gerą stebėtoją ir blogą smalsuolį. Jo tvirtinimą, kad nesikiša, komplikuoja elgesys, o frazė apie visiems naudingą tvarką skamba kaip savęs pateisinimas. Tačiau konkretus pagalbos atvejis neleidžia teigti, kad stebėjimas tekste vaizduojamas vien kaip beprasmė yda. Neužbaigtas įrašas gali reikšti abejonę, bet gali būti ir trumpas sutrikimas, kurio pasakotojas nepaaiškina. Pagrįsta interpretacija turėtų išlaikyti šią atvirą vietą, o ne priskirti veikėjui aiškų moralinį pasikeitimą, apie kurį tekstas tiesiogiai nepraneša.','«Yo nunca me meto en asuntos ajenos», dijo el vecino, y volvió a comprobar quién entraba en el departamento de enfrente. Llamaba a su cuaderno una ayuda para la memoria: al fin y al cabo, nadie puede recordarlo todo. Cuando alguien le preguntaba por qué necesitaba conocer los nombres de las visitas, sonreía apenas: «El orden nos beneficia a todos». Una noche llamó a su puerta una nueva vecina. Quería saber si había visto a su padre, que había salido a caminar y no había vuelto a la hora acordada. El vecino indicó enseguida qué dirección había tomado y qué abrigo llevaba. La mujer le dio las gracias. Al cerrar la puerta, miró satisfecho el cuaderno, pero por primera vez dejó sin terminar la anotación del día. Este fragmento original impide dividir al personaje de forma sencilla entre observador bondadoso y entrometido malicioso. Su afirmación de no intervenir queda complicada por sus actos, y la frase sobre el orden suena a justificación propia. Sin embargo, la ayuda concreta impide afirmar que observar se presente únicamente como un defecto inútil. La anotación incompleta podría sugerir una duda, pero también una vacilación momentánea que el narrador no explica. Una interpretación fundada debería conservar esa apertura, en vez de atribuir al personaje una transformación moral inequívoca que el texto no anuncia.','In an original fictional scene, a neighbour denies interfering while monitoring visitors and keeping a notebook. His defence of order sounds self-justifying. When a resident asks about her missing father, his observations help. He then leaves an entry unfinished. The commentary reads a discrepancy between self-description and action but rejects both an exclusively useless vice and a clearly established moral transformation. The unfinished entry leaves room for doubt or a temporary hesitation.'],
 listen:['Vienas skaitytojas teigė, kad neužbaigtas įrašas aiškiai rodo veikėjo atsivertimą. Man toks aiškinimas suprantamas, tačiau per kategoriškas. Tekste matome pasikeitusį veiksmą, bet nežinome, ar jis taps nauju įpročiu. Kitas skaitytojas visą epizodą laikė stebėjimo pateisinimu: juk užrašai padėjo kaimynei. Šis perskaitymas taip pat turi atramą, bet nepaaiškina pradžioje išryškinto neatitikimo tarp veikėjo žodžių ir elgesio. Man įtikinamesnė interpretacija, kuri pagalbos atvejį laiko ne galutiniu nuosprendžiu, o išbandymu ankstesnei veikėjo savivokai. Jis gali ir toliau save teisinti, tačiau dabar skaitytojui sunkiau priimti paprastą pasakojimą apie vien naudingą tvarką. Svarbu, kad ši išvada nepriklausytų nuo tariamai žinomo autoriaus ketinimo. Ją grindžia teksto sandara: pradinis savęs apibūdinimas, konkretus jo komplikavimas ir pabaigoje paliktas neužbaigtumas.','Un lector sostuvo que la anotación incompleta muestra claramente una conversión moral. Comprendo esa lectura, pero me parece demasiado categórica. Vemos una acción distinta, no sabemos si se convertirá en un hábito nuevo. Otra lectora interpretó el episodio entero como una justificación de la vigilancia: las notas ayudaron a la vecina. Esa lectura también tiene apoyo, pero no explica la discrepancia inicial entre las palabras y la conducta. Me resulta más convincente entender la ayuda como una prueba para la imagen que el personaje tiene de sí mismo, no como un veredicto definitivo. Puede seguir justificándose; aun así, al lector le cuesta más aceptar una historia de orden exclusivamente beneficioso. Es importante no hacer depender la conclusión de una supuesta intención conocida del autor. La sostiene la estructura: la descripción inicial de sí mismo, su complicación concreta y la falta de cierre que permanece al final.','The speaker qualifies the conversion reading: one changed action does not establish a new habit. A wholly pro-surveillance reading has evidence but neglects the opening discrepancy. The preferred reading treats the helpful episode as a test of the character’s self-image, not a final verdict. It rests on textual structure, not claimed knowledge of authorial intent.'],
 readQ:[['Where does the clearest initial discrepancy lie?',['Between the denial of interference and the monitoring','Between two stated dates','Between two versions of the woman’s name'],0],['What does the useful observation complicate?',['The fact that a notebook exists','A reading of observation as solely a useless vice','The resident’s request for help'],1],['What does the unfinished entry establish?',['A permanent moral transformation','The author’s confirmed intention','An unresolved detail permitting qualified interpretation'],2]],
 hearQ:[['Why qualify the conversion reading?',['No action changes at all','One changed action does not establish a lasting habit','The notebook has disappeared'],1],['What weakens the wholly approving reading?',['It neglects the opening discrepancy','It lacks any supporting detail','It proves authorial intention'],0],['What supports the preferred reading?',['A private statement by the author','A universal rule about all neighbours','The scene’s sequence and unresolved ending'],2]],
 turns:[['Ar pabaiga įrodo, kad veikėjas pasikeitė?','¿El final demuestra que el personaje ha cambiado?','Does the ending prove the character has changed?','Distinguish one action from a demonstrated lasting transformation.'],['Kuo pagrįstumėte kitokį perskaitymą?','¿En qué apoyaría una lectura diferente?','What would support another reading?','Offer a plausible alternative with a textual detail and a limit.'],['Paaiškinkite savo interpretaciją skaitytojui, kuris nesutinka.','Explique su interpretación a un lector que discrepa.','Explain your reading to someone who disagrees.','Acknowledge the strongest alternative while defending your emphasis through structure or wording.']],
 production:['Defend a nuanced interpretation of the original scene for a reading group.',['Anchor claims in wording or structure.','Represent a competing reading fairly.','Preserve what the ending leaves unresolved.']],
 mediation:'Introduce the competing interpretations to a reading group and explain why the spoken commentary qualifies both without declaring all readings equally valid.',
 project:{title:'A critical reading',audience:'A literary discussion group',brief:'Write a commentary engaging an alternative interpretation without claiming access to the author’s private intention.',goals:['Develop a reading grounded in wording or structure.','Test it against a credible alternative.','Distinguish an unresolved ending from unlimited interpretive freedom.'],range:[330,480]}}
,{id:'A1-travel',band:'A1',theme:'Find a stop and buy a ticket',focus:'Understand simple directions, a departure time and a ticket request.',
 phrases:[['stotelė','parada','bus stop'],['stotis','terminal','station / bus terminal'],['Eikite tiesiai.','Siga derecho.','Go straight.'],['Sukite į dešinę.','Dé vuelta a la derecha.','Turn right.'],['Sukite į kairę.','Dé vuelta a la izquierda.','Turn left.'],['Kur yra stotelė?','¿Dónde está la parada?','Where is the stop?'],['Vieną bilietą, prašau.','Un boleto, por favor.','One ticket, please.'],['Autobusas atvažiuoja dešimtą.','El autobús llega a las diez.','The bus arrives at ten.']],
 lesson:['Separate the walking directions from the bus destination.','The examples use polite directions: eikite / siga, sukite / dé vuelta. Follow the complete pattern.','A stop and a terminal are different places. Check the place, direction and time.'],
 reading:['Stotelė yra prie parko. Eikite tiesiai ir sukite į dešinę. Autobusas į stotį atvažiuoja dešimtą. Bilietą pirkite autobuse.','La parada está junto al parque. Siga derecho y dé vuelta a la derecha. El autobús a la terminal llega a las diez. Compre el boleto en el autobús.','The stop is beside the park. Go straight and turn right. The bus to the terminal arrives at ten. Buy the ticket on the bus.'],
 listen:['Stotelė yra prie parduotuvės. Eikite tiesiai, paskui sukite į kairę. Autobusas į stotį atvažiuoja vienuoliktą. Vieną bilietą galite nusipirkti autobuse.','La parada está junto a la tienda. Siga derecho y después dé vuelta a la izquierda. El autobús a la terminal llega a las once. Puede comprar un boleto en el autobús.','This stop is beside the shop. Go straight, then turn left. The terminal bus arrives at eleven. A ticket can be bought on the bus.'],
 readQ:[['What is beside the stop?',['The park','The shop','The library'],0],['Which turn is given?',['Left','Right','No turn'],1],['When does the bus arrive?',['Eleven','Nine','Ten'],2]],
 hearQ:[['Which turn is given in the recording?',['Right','Left','No turn'],1],['Where is this stop?',['Beside the shop','Inside the terminal','Beside the library'],0],['What time is mentioned?',['Ten','Twelve','Eleven'],2]],
 turns:[['Kur norėtumėte nuvažiuoti?','¿Adónde quiere ir?','Where would you like to go?','State a simple destination.'],['Ar žinote, kur yra stotelė?','¿Sabe dónde está la parada?','Do you know where the stop is?','Ask for the stop or check a direction.'],['Kiek bilietų norėtumėte?','¿Cuántos boletos quiere?','How many tickets would you like?','Request a quantity and close politely.']],
 production:['Explain how a visitor can find a stop and catch a bus.',['Locate the stop.','Give a direction.','State a time and ticket detail.']],
 mediation:'Tell a visitor how the written and spoken routes differ, especially the turning direction and bus time.',
 project:{title:'A short travel note',audience:'A visiting friend',brief:'Write simple directions to a real or invented stop, with a useful bus detail.',goals:['Locate the stop.','Give a clear direction.','Include a time or ticket instruction.'],range:[30,70]}},
{id:'A2-meals',band:'A2',theme:'Plan a meal for a group',focus:'Understand preferences, compare a plan with a changed order and make a practical request.',
 phrases:[['Nevalgau mėsos.','No como carne.','I do not eat meat.'],['Ar turite patiekalų be mėsos?','¿Tiene platillos sin carne?','Do you have dishes without meat?'],['Norėtume užsisakyti keturiems žmonėms.','Quisiéramos pedir para cuatro personas.','We would like to order for four people.'],['Padažą pateikite atskirai, prašau.','La salsa aparte, por favor.','The sauce separately, please.'],['Kiek laiko reikės laukti?','¿Cuánto hay que esperar?','How long is the wait?'],['Galime ateiti vėliau.','Podemos llegar más tarde.','We can come later.'],['Mūsų planas pasikeitė.','Nuestro plan cambió.','Our plan has changed.'],['Prašau patvirtinti užsakymą.','Confirme el pedido, por favor.','Please confirm the order.']],
 lesson:['Mention the number of people separately from individual food preferences.','A preference and a request for a separate sauce are distinct details. Do not infer ingredients that have not been confirmed.','When changing an order, state which details stay the same and which change.'],
 reading:['Šeštadienį norėtume užsisakyti vakarienę keturiems žmonėms. Du žmonės nevalgo mėsos, todėl jiems reikėtų patiekalų be mėsos. Kiti du norėtų vištienos. Padažą visiems pateikite atskirai. Galėtume atvykti septintą valandą. Jei reikės ilgiau laukti, praneškite žinute. Prieš atvykdami norėtume gauti užsakymo patvirtinimą.','El sábado quisiéramos pedir cena para cuatro personas. Dos no comen carne y necesitan platillos sin carne. Las otras dos quieren pollo. Sirvan la salsa aparte para todos, por favor. Podemos llegar a las siete. Si hay que esperar más, avísennos por mensaje. Quisiéramos recibir la confirmación del pedido antes de llegar.','The Saturday meal is for four: two meat-free meals and two chicken meals. Sauce should be separate for everyone. Arrival is seven; notify the group by message about a longer wait and confirm before arrival.'],
 listen:['Laba diena, mūsų vakarienės planas pasikeitė. Atvyksime penkiese, o ne keturiese, ir galėsime būti tik pusę aštuonių. Trims žmonėms reikės patiekalų be mėsos. Du vištienos patiekalai lieka. Padažą vis dar norėtume gauti atskirai. Ar galėtumėte patvirtinti naują žmonių skaičių ir laiką?','Buenos días, cambió nuestro plan para la cena. Vamos a llegar cinco personas, no cuatro, y solo podemos estar a las siete y media. Tres personas necesitan platillos sin carne. Los dos platos de pollo se mantienen. Seguimos queriendo la salsa aparte. ¿Podría confirmar el nuevo número de personas y la hora?','The order changes to five people at seven thirty, with three meat-free meals. Two chicken meals and the separate sauce request remain. The caller requests confirmation of the new number and time.'],
 readQ:[['How many meals without meat are requested?',['Two','Three','Four'],0],['How should the sauce be served?',['Only with chicken','Separately for everyone','Mixed into every dish'],1],['What should happen before arrival?',['Cancel every order','Change the day','Confirm the order'],2]],
 hearQ:[['How many people will now attend?',['Four','Five','Six'],1],['What remains unchanged?',['Two chicken meals','The arrival time','The number of meat-free meals'],0],['What is the new arrival time?',['Seven','Eight','Seven thirty'],2]],
 turns:[['Kiek žmonių bus jūsų grupėje?','¿Cuántas personas vienen en su grupo?','How many people are in your group?','Give the number of people.'],['Ar turite pageidavimų dėl patiekalų?','¿Tienen alguna preferencia para los platillos?','Do you have meal preferences?','Explain a preference and who it concerns.'],['Reikės palaukti pusvalandį. Ar jums tinka?','Hay que esperar media hora. ¿Les parece bien?','There is a half-hour wait. Does that work?','Accept the wait or propose an alternative and ask for confirmation.']],
 production:['Explain a group meal order and a change to it.',['Give the group size.','Distinguish preferences clearly.','State a change and ask for confirmation.']],
 mediation:'Explain the revised order to a friend, preserving the two chicken meals while updating the group size, meat-free meals and time.',
 project:{title:'Update a group order',audience:'A restaurant',brief:'Write a practical change to an invented group meal order.',goals:['Identify the changed group size or time.','Explain which meal requests change and which remain.','Request confirmation.'],range:[70,120]}},
{id:'B1-housing',band:'B1',theme:'Arrange a household repair',focus:'Report an observed problem, distinguish an estimate from a promise and agree access arrangements.',
 phrases:[['Virtuvėje laša čiaupas.','La llave de la cocina gotea.','The kitchen tap is dripping.'],['Problema prasidėjo vakar.','El problema empezó ayer.','The problem started yesterday.'],['Norėčiau susitarti dėl apsilankymo.','Quisiera acordar una visita.','I would like to arrange a visit.'],['Pirmadienį ryte nebūsiu namuose.','El lunes por la mañana no voy a estar en casa.','I will not be home on Monday morning.'],['Galite atvykti po trečios valandos.','Puede venir después de las tres.','You can come after three.'],['Kol kas negaliu pasakyti, kiek tai užtruks.','Por ahora no puedo decir cuánto va a tardar.','For now I cannot say how long it will take.'],['Prašau iš anksto pranešti apie pasikeitimus.','Avise con anticipación si hay cambios, por favor.','Please give advance notice of changes.'],['Patvirtinkime laiką raštu.','Confirmemos el horario por escrito.','Let us confirm the time in writing.']],
 lesson:['Report what you observed without inventing a technical diagnosis.','An arrival window, an estimated repair time and a guaranteed finish are different claims.','A useful arrangement states who can provide access and how changes will be communicated.'],
 reading:['Vakar pastebėjau, kad virtuvėje laša čiaupas. Parašiau meistrui ir paprašiau atvykti pirmadienį. Jis pasiūlė laiką nuo devintos iki vienuoliktos, tačiau tuo metu nebūsiu namuose. Paprašiau vizitą perkelti po trečios valandos. Meistras paaiškino, kad pirmiausia turės apžiūrėti čiaupą ir tik tada galės pasakyti, kiek užtruks remontas. Sutarėme, kad iki sekmadienio vakaro patvirtinsime apsilankymo laiką raštu. Kaimyno prašyti įleisti meistrą kol kas nereikia: popietę būsiu namuose pats.','Ayer noté que la llave de la cocina gotea. Le escribí a un técnico y le pedí una visita el lunes. Propuso llegar entre las nueve y las once, pero no voy a estar en casa a esa hora. Pedí cambiar la visita para después de las tres. El técnico explicó que primero tendría que revisar la llave y solo entonces podría decir cuánto tardaría la reparación. Acordamos confirmar el horario por escrito antes del domingo por la noche. Por ahora no hace falta pedirle al vecino que abra: yo voy a estar en casa por la tarde.','A dripping tap prompts a Monday visit request. The initial nine-to-eleven window does not work, so the resident requests after three. The technician must inspect before estimating repair duration. They will confirm the visit by Sunday evening. The resident, not a neighbour, will provide afternoon access.'],
 listen:['Skambinu dėl pirmadienio vizito. Galėčiau atvykti tarp ketvirtos ir penktos, jeigu jums tinka. Tai yra atvykimo laikas, o ne pažadas iki penktos baigti remontą. Jei apžiūrėjęs pamatysiu, kad reikia kitos detalės, aptarsime atskirą laiką darbui užbaigti. Prašau šiandien patvirtinti, ar tuo metu būsite namuose. Jei mano ankstesnis darbas užtruks, paskambinsiu prieš išvažiuodamas.','Le llamo por la visita del lunes. Podría llegar entre las cuatro y las cinco, si le viene bien. Ese es el horario de llegada, no una promesa de terminar la reparación antes de las cinco. Si al revisar veo que hace falta otra pieza, acordaremos otro horario para terminar. Confirme hoy si va a estar en casa, por favor. Si el trabajo anterior se alarga, llamaré antes de salir.','The technician offers Monday arrival between four and five, not a guarantee of completion by five. Another part may require a later visit. The resident should confirm today; the technician will call before departure if delayed.'],
 readQ:[['Why reject the initial visit window?',['The resident will be away','The neighbour refuses to help','The repair is already complete'],0],['When can the technician estimate repair duration?',['Before reading the message','After inspecting the tap','Only after Sunday has passed'],1],['Who plans to provide afternoon access?',['The neighbour','Nobody','The resident'],2]],
 hearQ:[['What does four-to-five describe?',['A guaranteed completion deadline','An arrival window','The price of a part'],1],['What could require a further arrangement?',['A needed replacement part','The resident confirming today','A written message'],0],['What will happen if the earlier job runs late?',['The visit will silently disappear','A neighbour will automatically open','The technician will call before leaving'],2]],
 turns:[['Kokią problemą pastebėjote?','¿Qué problema ha observado?','What problem have you observed?','Describe the observed problem and when it began.'],['Ar galėtumėte mane įleisti pirmadienį ryte?','¿Podría recibirme el lunes por la mañana?','Could you let me in on Monday morning?','Respond with your availability and a practical alternative.'],['Negaliu pažadėti, kad remontą užbaigsiu tą pačią dieną.','No puedo prometer que termine la reparación ese mismo día.','I cannot promise to finish the repair that day.','Check what is confirmed and what remains uncertain.']],
 production:['Explain a household problem and a workable visit arrangement.',['Separate observations from assumptions.','Give clear access arrangements.','Distinguish arrival from repair completion.']],
 mediation:'Brief a household member on the confirmed arrival window, the uncertain repair duration and the resident’s response deadline.',
 project:{title:'Confirm a repair visit',audience:'A technician and a household member',brief:'Write a clear confirmation for an invented household repair visit.',goals:['Describe the problem without inventing its cause.','Confirm access and an arrival window.','Preserve any uncertainty about completion and ask for notice of changes.'],range:[120,190]}}
,{id:'B2-mobility',band:'B2',theme:'Balance access in a public space',focus:'Compare a proposal and its conditions, address competing needs and define a fair trial.',
 phrases:[['Siūloma apriboti automobilių eismą.','Se propone limitar el tránsito de automóviles.','A restriction on car traffic is proposed.'],['Tai palengvintų judėjimą pėstiesiems.','Eso facilitaría el paso de los peatones.','That would make movement easier for pedestrians.'],['Reikia numatyti pristatymo galimybę.','Hay que prever el acceso para entregas.','Delivery access must be planned.'],['Ne visi gali atvykti tuo pačiu būdu.','No todos pueden llegar del mismo modo.','Not everyone can arrive in the same way.'],['Palaikau bandymą, bet ne besąlygišką plėtrą.','Apoyo una prueba, no una ampliación sin condiciones.','I support a trial, not unconditional expansion.'],['Svarbu išgirsti skirtingas grupes.','Es importante escuchar a distintos grupos.','It is important to hear different groups.'],['Vidurkis gali paslėpti dalies žmonių sunkumus.','Un promedio puede ocultar las dificultades de algunas personas.','An average can hide difficulties for some people.'],['Sprendimą peržiūrėtume po bandymo.','Revisaríamos la decisión después de la prueba.','We would review the decision after the trial.']],
 lesson:['Agreement with a goal does not imply agreement with every condition of a proposal.','Distinguish a limited trial from a decision to expand permanently.','Evaluate who can actually use a space, rather than treating one average as the whole result.'],
 reading:['Išgalvoto rajono taryba siūlo du mėnesius savaitgaliais riboti automobilių eismą pagrindinėje gatvėje. Tikimasi, kad pėstiesiems bus patogiau pasiekti parką ir mažas parduotuves. Prekybininkų grupė palaiko patrauklesnės gatvės tikslą, tačiau prašo iš anksto nustatyti prekių pristatymo valandas. Kai kurie gyventojai taip pat primena, kad ne visi gali atvykti pėsčiomis ar dviračiu. Todėl plane reikėtų aiškiai numatyti prieinamą išlaipinimo vietą ir informuoti apie kitus atvykimo būdus. Projekto šalininkai siūlo vertinti lankytojų skaičių, o kritikai prašo atskirai išklausyti tuos, kuriems atvykti tapo sunkiau. Šie kriterijai neprivalo vienas kito paneigti. Bandymo rezultatas būtų naudingesnis, jei parodytų ir bendrą pokytį, ir konkrečias likusias kliūtis.','El consejo de un barrio ficticio propone restringir el tránsito en la calle principal durante los fines de semana de dos meses. Se espera facilitar el acceso peatonal al parque y a las tiendas pequeñas. Un grupo de comerciantes apoya la idea de una calle más agradable, pero pide fijar con anticipación horarios para las entregas. Algunos vecinos recuerdan que no todos pueden llegar caminando o en bicicleta. Por eso el plan debería prever una zona accesible para dejar pasajeros e informar sobre otras formas de llegar. Los defensores proponen medir el número de visitantes; los críticos piden escuchar por separado a quienes encuentran nuevas dificultades. Esos criterios no tienen por qué excluirse. La prueba sería más útil si mostrara tanto el cambio general como las barreras concretas que persisten.','A fictional council proposes a two-month weekend traffic trial. Businesses support a more welcoming street but want delivery times. Residents request accessible passenger drop-off and alternative travel information. Visitor totals and the experiences of people facing access barriers can both inform evaluation.'],
 listen:['Manau, kad galime pradėti ribotą bandymą, tačiau jo sąlygas reikia paskelbti prieš pirmą savaitgalį. Prekių pristatymui siūlau palikti dvi valandas ryte. Taip pat būtina nurodyti, kur galima saugiai išleisti keleivį, kuris negali ilgai eiti. Po pirmo mėnesio reikėtų patikrinti, ar šios išimtys iš tiesų veikia. Jei daugėja lankytojų, bet dalis gyventojų nuolat nebegali pasiekti parduotuvių, vien didesnio bendro skaičiaus nepakanka plėtrai pagrįsti. Kita vertus, pavienis sunkumas neturėtų automatiškai nutraukti viso bandymo: pirmiausia reikėtų suprasti jo priežastį ir pabandyti ją pašalinti. Palaikau tokį bandymą, kurį galima koreguoti pagal aiškiai surinktą informaciją.','Creo que podemos iniciar una prueba limitada, pero debemos publicar las condiciones antes del primer fin de semana. Propongo reservar dos horas por la mañana para las entregas. También hace falta indicar dónde puede bajar con seguridad una persona que no puede caminar mucho. Después del primer mes habría que comprobar si esas excepciones funcionan de verdad. Si aumentan las visitas, pero algunos vecinos siguen sin poder llegar a las tiendas, el total no basta para justificar la ampliación. Por otra parte, una dificultad aislada tampoco debería cancelar automáticamente toda la prueba: primero hay que comprenderla e intentar resolverla. Apoyo una prueba que pueda ajustarse según información recogida de forma clara.','The speaker supports a conditional trial: publish conditions beforehand, reserve two morning hours for deliveries and specify accessible drop-off. Review exceptions after one month. More visitors alone do not justify expansion if persistent barriers remain, while one isolated problem should prompt investigation rather than automatic cancellation.'],
 readQ:[['What does the business group request?',['Defined delivery times','A permanent ban on all visitors','The removal of every shop'],0],['Why mention different ways of arriving?',['To prove every visitor rides a bicycle','To consider people who cannot walk or cycle there','To reject all pedestrian access'],1],['How are the two evaluation approaches related?',['Only one can be used','Neither provides useful information','They can describe complementary effects'],2]],
 hearQ:[['When should exceptions first be checked?',['After permanent expansion','After the first month','Only after several years'],1],['What is insufficient on its own to justify expansion?',['A higher total visitor count','Published delivery hours','Understanding a particular barrier'],0],['What response to an isolated problem fits the speaker?',['Ignore it because most visitors are happy','Cancel automatically','Investigate and try to resolve it'],2]],
 turns:[['Kokį bandymą siūlytumėte šiai gatvei?','¿Qué prueba propondría para esta calle?','What trial would you propose for this street?','Recommend a limited arrangement with a reason.'],['Kaip atsižvelgsite į pristatymus ir skirtingas atvykimo galimybes?','¿Cómo tendrá en cuenta las entregas y las distintas formas de llegar?','How will you consider deliveries and different access needs?','Address two practical needs without dismissing either.'],['Kokie rezultatai leistų bandymą plėsti arba keisti?','¿Qué resultados justificarían ampliar o modificar la prueba?','What results would justify expansion or adjustment?','State criteria and a meaningful condition for revision.']],
 production:['Recommend a trial for a fictional public space while balancing competing access needs.',['Explain the goal and conditions.','Address a credible practical objection.','Use more than one evaluation criterion.']],
 mediation:'Explain to a resident how the spoken proposal adds practical conditions and an early review to the written two-month trial.',
 project:{title:'A balanced trial proposal',audience:'A neighbourhood committee',brief:'Write a conditional proposal for a fictional public-space trial.',goals:['Explain a benefit and a practical constraint.','Provide workable access or delivery arrangements.','Define evaluation and revision criteria.'],range:[190,280]}},
{id:'C1-professional',band:'C1',theme:'Clarify a professional commitment',focus:'Distinguish an estimate from a commitment and communicate uncertainty without losing accountability.',
 phrases:[['Preliminari data nėra besąlygiškas pažadas.','Una fecha provisional no es una promesa incondicional.','A provisional date is not an unconditional promise.'],['Laiške nurodyta sąlyga liko neaptarta.','La condición del correo quedó sin aclarar.','The condition in the email remained unresolved.'],['Reikia suderinti abiejų šalių supratimą.','Hay que conciliar lo que entendieron ambas partes.','Both parties’ understanding needs to be reconciled.'],['Nenorėčiau priskirti kolegai nepasakyto pažado.','No quisiera atribuirle al colega una promesa que no hizo.','I would not attribute an unmade promise to the colleague.'],['Vis dėlto neaiškumą turime išspręsti.','Aun así, tenemos que resolver la ambigüedad.','Nevertheless, we need to resolve the ambiguity.'],['Prašau patvirtinti, nuo ko priklauso terminas.','Confirme de qué depende el plazo, por favor.','Please confirm what the deadline depends on.'],['Atsakomybė už kitą veiksmą turi būti aiški.','La responsabilidad del siguiente paso debe quedar clara.','Responsibility for the next step must be clear.'],['Atnaujintą planą pateiksime raštu.','Presentaremos el plan actualizado por escrito.','We will provide the updated plan in writing.']],
 lesson:['A time estimate qualified by a condition is different from an unconditional delivery commitment.','Avoid inventing someone’s intention when explaining an ambiguous exchange. Attribute what was actually said.','A diplomatic clarification still needs a responsible person, next action and confirmation point.'],
 reading:['Išgalvotos projekto komandos laiške parašyta: „Tikimės ataskaitą pateikti penktadienį, jei iki trečiadienio gausime galutinę specifikaciją.“ Susitikimo užrašuose vėliau liko tik sakinys „Ataskaita bus penktadienį“. Klientas šį įrašą suprato kaip patvirtintą terminą. Komanda tvirtina pateikusi sąlyginį vertinimą, o ne besąlygišką pažadą. Būtų netikslu iš karto nuspręsti, kad viena pusė sąmoningai klaidina kitą. Tačiau vien geranoriško ketinimo neužtenka nesusipratimui pašalinti. Reikia atkurti, kokia sąlyga buvo nurodyta, ar ji įvykdyta ir kas turi patvirtinti naują datą. Tarpininkas siūlo atnaujinti susitikimo įrašą taip, kad jame būtų matoma ir preliminari data, ir jos priklausomybė nuo specifikacijos. Atskiru sakiniu turėtų būti nurodyta, kas informuos klientą, jei ši priklausomybė pakeis grafiką.','En el correo de un equipo ficticio se lee: «Esperamos entregar el informe el viernes si recibimos la especificación definitiva antes del miércoles». En las notas de la reunión quedó después solo «El informe estará el viernes». El cliente interpretó esa frase como un plazo confirmado. El equipo sostiene que dio una estimación condicional, no una promesa incondicional. Sería inexacto decidir de inmediato que alguien intentó engañar a la otra parte. Pero una intención de buena fe tampoco basta para resolver el malentendido. Hay que reconstruir qué condición se mencionó, si se cumplió y quién debe confirmar una fecha nueva. La persona que media propone corregir el acta para que muestre la fecha provisional y su dependencia de la especificación. Otra frase debería indicar quién avisará al cliente si esa dependencia modifica el calendario.','An email estimated Friday delivery if final specifications arrived by Wednesday. Meeting notes dropped the condition, and the client understood a confirmed deadline. The source does not establish deliberate deception. Clarification should reconstruct the condition, whether it occurred, who confirms a date and who notifies the client of changes.'],
 listen:['Galutinė specifikacija dar nepatvirtinta, todėl šiandien negalime patikimai patvirtinti penktadienio datos. Tai nereiškia, kad ataskaita būtinai vėluos; reiškia, kad pirminio vertinimo sąlyga dar neįvykdyta. Siūlau iki rytojaus vidurdienio atskirai suderinti trūkstamas detales. Už tai būsiu atsakinga aš. Po šio patikslinimo komandos vadovas pateiks atnaujintą grafiką ir paaiškins, kurios jo dalys jau patvirtintos, o kurios dar priklauso nuo papildomų sprendimų. Klientui nereikėtų siųsti vien neapibrėžto pažado pasistengti. Naudingesnis būtų konkretus paaiškinimas, ką dabar galime padaryti, ko dar nežinome ir kada pateiksime kitą informaciją.','La especificación definitiva todavía no está confirmada, así que hoy no podemos confirmar con fiabilidad la fecha del viernes. Eso no significa que el informe vaya a retrasarse necesariamente; significa que aún no se cumple la condición de la estimación original. Propongo aclarar los detalles pendientes antes de mañana al mediodía. Yo me encargo de esa tarea. Después, el responsable del equipo enviará un calendario actualizado y distinguirá las partes confirmadas de las que dependen de otras decisiones. Al cliente no le serviría recibir solo una promesa vaga de hacer lo posible. Necesita saber qué podemos hacer ahora, qué no sabemos todavía y cuándo recibirá la siguiente información.','Final specifications are unconfirmed, so Friday cannot yet be reliably confirmed; delay is not established as inevitable. The speaker will clarify details by tomorrow noon. The team lead will then send an updated schedule distinguishing confirmed and conditional elements, with a concrete next-information point rather than a vague promise.'],
 readQ:[['What was lost from the meeting notes?',['The condition on the Friday estimate','The name of the report','A confirmed payment'],0],['What does the source justify concluding about intent?',['The client certainly lied','Deliberate deception is not established','The team made no statement at all'],1],['What should an effective clarification include?',['Only a general reassurance','An accusation without evidence','The condition, next responsibility and confirmation process'],2]],
 hearQ:[['Does the speaker say delay is inevitable?',['Yes, it is certain','No, the original condition is still unresolved','No, Friday is guaranteed'],1],['Who will clarify the missing details?',['The speaker','The client alone','Nobody is identified'],0],['What happens after clarification?',['The old incomplete notes become final automatically','All communication stops','The team lead supplies an updated, qualified schedule'],2]],
 turns:[['Ar komanda pažadėjo pristatyti ataskaitą penktadienį?','¿El equipo prometió entregar el informe el viernes?','Did the team promise Friday delivery?','Distinguish the qualified estimate from the shortened note.'],['Kaip paaiškintumėte situaciją nekaltindami kliento?','¿Cómo explicaría la situación sin culpar al cliente?','How would you explain this without blaming the client?','Acknowledge the understandable interpretation and restore the missing condition.'],['Kas konkrečiai turi įvykti toliau?','¿Qué tiene que pasar ahora, concretamente?','What specifically must happen next?','Name responsibility, the next action and an information deadline.']],
 production:['Brief both parties on an ambiguous professional commitment.',['Attribute the original wording accurately.','Preserve uncertainty without implying inevitable failure.','Make responsibility and the next update concrete.']],
 mediation:'Reconcile the email, shortened meeting note and spoken update for a decision-maker who has seen only the note.',
 project:{title:'A professional clarification',audience:'A client and project team',brief:'Write a tactful clarification of the fictional Friday estimate and the updated process.',goals:['Explain how the two formulations differ without inventing intent.','Distinguish confirmed facts, uncertainty and commitments.','Give a responsible next step and update point.'],range:[250,380]}},
{id:'C2-register',band:'C2',theme:'Change register without changing force',focus:'Reformulate for different audiences while preserving conditions, responsibility and the force of a decision.',
 phrases:[['Mandagus tonas nepanaikina reikalavimo.','El tono cortés no elimina el requisito.','A courteous tone does not remove the requirement.'],['Formuluotės švelnumas nėra sąlygos atsisakymas.','La suavidad de la formulación no supone renunciar a la condición.','Soft wording does not abandon the condition.'],['Reikia išsaugoti sprendimo loginę struktūrą.','Hay que conservar la estructura lógica de la decisión.','The decision’s logical structure must be preserved.'],['Sutrumpinimas neturėtų pakeisti įsipareigojimo.','La reducción no debería modificar el compromiso.','Shortening should not change the commitment.'],['Šiame kontekste užuomina patikslinta tiesioginiu teiginiu.','En este contexto la insinuación se precisa con una afirmación explícita.','In this context an implication is clarified explicitly.'],['Negalima numanyto ketinimo pateikti kaip cituoto fakto.','No debe presentarse una intención inferida como un hecho citado.','An inferred intention must not be presented as a quoted fact.'],['Skirtingam skaitytojui reikia kitokio paaiškinimo.','Un lector distinto necesita otra explicación.','A different reader needs a different explanation.'],['Esmė lieka ta pati, nors registras keičiasi.','El contenido esencial se mantiene aunque cambie el registro.','The essential content remains while register changes.']],
 lesson:['Do not infer the force of a polite phrase from wording alone when the surrounding context supplies an explicit decision.','A short public version can omit procedural detail, but must retain any condition that changes the outcome.','Separate quoted words, contextual inference and your own proposed reformulation.'],
 reading:['Išgalvoto komiteto pirmininkė, aptardama ataskaitą, pasako: „Gal vertėtų dar kartą pagalvoti apie šios išvados pagrindimą.“ Vien iš tokios frazės nebūtų saugu spręsti, ar ji išsako neprivalomą pasiūlymą, ar santūriai formuluoja esminį prieštaravimą. Tačiau toliau pirmininkė aiškiai nurodo: „Kol nebus atskirta stebėta nauda nuo numanomos priežasties, išvados netvirtinsime.“ Šiame kontekste pirmosios frazės mandagumas nepanaikina antrosios nustatytos sąlygos. Rengiant trumpą pranešimą visuomenei būtų klaidinga rašyti, kad komitetas tik pasiūlė neprivalomą stilistinį pataisymą. Lygiai taip pat būtų netikslu teigti, kad visa ataskaita galutinai atmesta. Sprendimas yra sąlyginis: išvados tvirtinimas atidėtas, kol bus išspręstas konkretus pagrindimo klausimas. Skirtingiems skaitytojams galima pasirinkti skirtingą registrą. Komandai reikalingas tikslus paaiškinimas, ką taisyti; visuomenei – aiški sprendimo esmė ir jo sąlyga. Vis dėlto nė viename variante neturėtų dingti tai, nuo ko priklauso tolesnis sprendimas. Reformulavimo kokybę čia rodo ne vien sklandumas, bet ir išsaugotas santykis tarp pastabos, reikalavimo ir galimo patvirtinimo.','La presidenta de un comité ficticio comenta un informe: «Quizá convendría reconsiderar el fundamento de esta conclusión». La frase aislada no permite decidir con seguridad si ofrece una sugerencia opcional o formula con prudencia una objeción sustancial. Sin embargo, a continuación precisa: «No aprobaremos la conclusión hasta que se distinga el beneficio observado de la causa supuesta». En ese contexto, la cortesía de la primera frase no elimina la condición de la segunda. Al redactar una nota pública sería engañoso decir que el comité solo sugirió un retoque estilístico opcional. También sería inexacto afirmar que rechazó definitivamente todo el informe. La decisión es condicional: se pospone la aprobación de la conclusión hasta resolver un problema concreto de fundamentación. Puede cambiarse el registro según el lector. El equipo necesita saber exactamente qué corregir; el público necesita comprender la decisión y su condición. Ninguna versión debería omitir aquello de lo que depende el siguiente paso. La calidad de la reformulación no se mide solo por su fluidez, sino por conservar la relación entre observación, requisito y posible aprobación.','A fictional chair first makes a polite suggestion to reconsider support for a conclusion, then explicitly withholds approval until observed benefit is distinguished from assumed cause. Context clarifies the force. Neither an optional stylistic edit nor permanent rejection accurately represents the conditional decision. Team and public versions may differ in register but must preserve the requirement and its relation to possible approval.'],
 listen:['Viešai siūlyčiau rašyti taip: komitetas prašo patikslinti išvados pagrindimą ir sprendimą dėl jos tvirtinimo priims po pataisymo. Tačiau komandos vidiniame laiške būtinas didesnis tikslumas. Reikia nurodyti, kurioje pastraipoje stebėtas pokytis pateikiamas kaip įrodyta priežastis ir kas turi tą vietą peržiūrėti. Taip pat svarbu nesukurti naujo pažado: pataisymas pats savaime negarantuoja patvirtinimo, nes komitetas dar turės įvertinti jo pakankamumą. Dėl to frazė „patvirtinsime po pataisymo“ būtų per stipri. Tikslesnė formuluotė būtų „po pataisymo grįšime prie tvirtinimo klausimo“. Ši išlyga gali atrodyti maža, bet ji atskiria įsipareigojimą dar kartą svarstyti nuo pažado pritarti. Trumpindami tekstą turime išsaugoti būtent tokias sprendimą keičiančias skirtis.','Para el público propondría decir que el comité solicita precisar el fundamento de la conclusión y retomará la decisión sobre su aprobación después de la revisión. El correo interno necesita más detalle: debe identificar el párrafo que presenta un cambio observado como causa probada y quién lo revisará. También hay que evitar inventar una promesa. La corrección no garantiza por sí sola la aprobación, porque el comité aún deberá valorar si resulta suficiente. Por eso «aprobaremos después de corregir» sería demasiado fuerte. «Retomaremos la cuestión de la aprobación después de la revisión» sería más preciso. La salvedad puede parecer pequeña, pero distingue el compromiso de volver a examinar del compromiso de aceptar. Al abreviar, debemos conservar precisamente esas diferencias que modifican la decisión.','A public version should say the committee requests better support and will revisit approval after revision. An internal version should identify the paragraph and responsible reviewer. Revision does not guarantee approval: reconsidering is not promising acceptance. A concise reformulation must preserve that decision-changing distinction.'],
 readQ:[['What clarifies the force of the first polite comment?',['The explicit condition that follows','A universal rule that polite suggestions are always mandatory','The report’s length'],0],['Which summary overstates rejection?',['Approval of the conclusion is postponed pending clarification','The entire report has been permanently rejected','The reasoning needs correction'],1],['What should both audience versions preserve?',['Exactly the same number of words','Every technical term regardless of audience','The condition governing the decision'],2]],
 hearQ:[['Why is “we will approve after revision” too strong?',['It is too long','Revision still needs to be judged sufficient','The committee has promised never to read it'],1],['What additional detail belongs in the internal version?',['The paragraph and responsible reviewer','A fabricated promise of approval','An assertion that the issue is only style'],0],['What distinction must survive shortening?',['Friendly versus unfriendly punctuation','Old versus new document titles','Reconsideration versus guaranteed acceptance'],2]],
 turns:[['Ar mandagiai suformuluota pastaba čia buvo neprivaloma?','¿La observación cortés era opcional en este contexto?','Was the courteous comment optional in this context?','Use the explicit surrounding condition rather than a universal assumption about polite language.'],['Kaip šį sprendimą pristatytumėte visuomenei?','¿Cómo presentaría esta decisión al público?','How would you present the decision publicly?','Give a concise account preserving the conditional status.'],['O ką tiksliai parašytumėte už pataisymą atsakingai komandai?','¿Y qué escribiría exactamente al equipo responsable de la revisión?','What exactly would you write to the team responsible for revision?','Specify the next action without inventing guaranteed approval.']],
 production:['Reformulate a conditional committee decision for two audiences.',['Separate quoted wording from contextual interpretation.','Adapt detail and register to each audience.','Preserve the distinction between reconsideration and acceptance.']],
 mediation:'Explain why the written decision and spoken wording advice allow different registers but do not permit a promise of automatic approval.',
 project:{title:'Two registers, one decision',audience:'A project team and the public',brief:'Write a short public notice and a separate internal note about the same fictional decision.',goals:['Use different detail and register for the two readers.','Preserve the condition and avoid inventing intent.','Distinguish promised reconsideration from guaranteed approval.'],range:[330,480]}}
];
function build(r){const reading=pick(r.reading),writing={id:r.id,title:r.theme,focus:r.focus,phrases:r.phrases.map(p=>[pick(p),p[2]]),lesson:r.lesson,model:reading,meaning:r.reading[2],questions:r.readQ,rubric:r.project.goals,projects:[]};return {id:r.id,band:r.band,theme:r.theme,focus:r.focus,writing,reading,readingGuide:r.reading[2],listen:pick(r.listen),translation:r.listen[2],notes:r.lesson,readingQuestions:r.readQ,questions:r.hearQ,turns:r.turns.map(t=>[pick(t),t[2],t[3]]),strategies:[0,4,7].map(i=>writing.phrases[i]),production:r.production,mediation:r.mediation,project:r.project,language:LANG.code};}
const extra=rows.map(build),units=base.levels.flatMap(level=>[level,...extra.filter(u=>u.band===level.id)]);
window.WordamiSkillsContent=Object.freeze({...base,units});
})();
